TOPICJ(47,{"14101":["abudawud",4918,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مومن مومن کا آئینہ ہے، اور مومن مومن کا بھائی ہے، وہ اس کی جائیداد کی نگرانی کرتا اور اس کی غیر موجودگی میں اس کی حفاظت کرتا ہے\"۔"],"14103":["bukhari",1401,"ہم سے محمد بن عبداللہ بن نمیر نے بیان کیا ‘ کہا کہ مجھ سے میرے والد نے بیان کیا ‘ کہا کہ ہم سے اسماعیل بن خالد نے بیان کیا ‘ ان سے قیس بن ابی حازم نے بیان کیا کہ جریر بن عبداللہ رضی اللہ عنہ نے کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے نماز قائم کرنے ‘ زکوٰۃ دینے اور ہر مسلمان کے ساتھ خیر خواہی کرنے پر بیعت کی تھی۔"],"14104":["bukhari",6083,"ہم سے محمد بن صباح نے بیان کیا، کہا ہم سے اسماعیل بن زکریا نے بیان کیا، کہا ہم سے عاصم بن سلیمان احول نے بیان کیا، کہا کہ میں نے انس بن مالک رضی اللہ عنہ سے پوچھا، کیا تم کو یہ بات معلوم ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ اسلام میں معاہدہ(حلف) کی کوئی اصل نہیں؟ انس رضی اللہ عنہ نے فرمایا کہ نبی کریم صلی اللہ علیہ وسلم نے خود قریش اور انصار کے درمیان میرے گھر میں حلف کرائی تھی۔"],"14105":["bukhari",2293,"ہم سے قتیبہ نے بیان کیا، کہا کہ ہم سے اسماعیل بن جعفر نے بیان کیا، ان سے حمید نے اور ان سے انس رضی اللہ عنہ نے کہ جب عبدالرحمٰن بن عوف رضی اللہ عنہ ہمارے یہاں آئے تھے تو رسول اللہ صلی اللہ علیہ وسلم نے ان کا بھائی چارہ سعد بن ربیع رضی اللہ عنہ سے کرایا تھا۔"],"14106":["muslim",6507,"سعد بن ابراہیم نے ا پنے والد سے ، انھوں نے سیدنا جبیربن مطعم رضی اللہ تعالیٰ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نےفرمایا : \" اسلام میں ایک دوسرے کو حلیف بنانے کی ضرورت نہیں ، جو شخص کا جاہلیت میں جو حلف تھا ، اسلام نے اس کی مضبوطی میں اور اضافہ کیا ۔"],"14107":["tirmidhi",1585,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے خطبہ میں فرمایا: \"جاہلیت کے حلف (معاہدہ تعاون) کو پورا کرو، اس لیے کہ اس سے اسلام کی مضبوطی میں اضافہ ہی ہوتا ہے اور اب اسلام میں کوئی نیا معاہدہ تعاون نہ کرو\"۔"],"14109":["bukhari",6484,"ہم سے ابونعیم نے بیان کیا، کہا ہم سے زکریا نے بیان کیا، ان سے عامر نے بیان کیا، انہوں نے عبداللہ بن عمر رضی اللہ عنہما سے سنا، کہا کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا مسلمان وہ ہے جو مسلمانوں کو اپنی زبان اور ہاتھ سے (تکلیف پہنچنے سے) محفوظ رکھے اور مہاجر وہ ہے جو ان چیزوں سے رک جائے جس سے اللہ نے منع کیا ہے۔ 27- بَابُ قَوْلِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «لَوْ تَعْلَمُونَ مَا أَعْلَمُ لَضَحِكْتُمْ قَلِيلاً، وَلَبَكَيْتُمْ كَثِيرًا»:"],"14110":["bukhari",11,"ہم کو سعید بن یحیی بن سعید اموی قریشی نے یہ حدیث سنائی، انہوں نے اس حدیث کو اپنے والد سے نقل کیا، انہوں نے ابوبردہ بن عبداللہ بن ابی بردہ سے، انہوں نے ابی بردہ سے، انہوں نے ابوموسیٰ رضی اللہ عنہ سے، وہ کہتے ہیں کہ لوگوں نے پوچھا یا رسول اللہ! کون سا اسلام افضل ہے؟ تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا وہ جس کے ماننے والے مسلمانوں کی زبان اور ہاتھ سے سارے مسلمان سلامتی میں رہیں۔"],"14111":["muslim",80,"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ کہتے ہوئے سنا : ’’ مسلمان وہ ہے جس کی زبان اور ہاتھ سے دوسرے مسلمان محفوظ رہیں"],"14113":["tirmidhi",2627,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمان (کامل) وہ ہے جس کی زبان اور ہاتھ (کے شر) سے دوسرے مسلمان محفوظ رہیں، اور مومن (کامل) وہ ہے جس سے لوگ اپنی جانوں اور اپنے مالوں کو محفوظ سمجھیں\"۔"],"14114":["ibnmajah",3934,"فضالہ بن عبید رضی اللہ عنہ بیان کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"مومن وہ ہے جس سے لوگوں کو اپنی جان اور مال کا خوف اور ڈر نہ ہو، اور مہاجر وہ ہے جو برائیوں اور گناہوں کو ترک کر دے\"۔"],"14115":["bukhari",7072,"ہم سے محمد بن یحیی ذہلی (یا محمد بن رافع) نے بیان کیا، کہا ہم کو عبدالرزاق نے خبر دی، انہیں معمر نے، انہیں ہمام نے، انہوں نے ابوہریرہ رضی اللہ عنہ سے سنا کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا کوئی شخص اپنے کسی دینی بھائی کی طرف ہتھیار سے اشارہ نہ کرے کیونکہ وہ نہیں جانتا ممکن ہے شیطان اسے اس کے ہاتھ سے چھڑوا دے اور پھر وہ کسی مسلمان کو مار کر اس کی وجہ سے جہنم کے گڑھے میں گر پڑے۔"],"14116":["muslim",6710,"ایوب نے ( محمد ) ابن سیرین سے روایت کی ، کہا : میں نے سیدنا ابوہریرہ رضی اللہ عنہ کو یہ کہتے ہوئے سنا کہ ابوالقاسم صلی اللہ علیہ وسلم نے فرمایا : \" جس نے اپنے بھائی کی طرف لوہے کے کسی ہتھیار سے اشارہ کیا تو اس پر فرشتے لعنت کرتے رہتے ہیں یہاں تک کہ وہ اس کام کو ترک کر دے ، چاہے وہ اس کا ماں باپ جایا بھائی ہی کیوں نہ ہو ۔"],"14117":["muslim",202,"سہیل بن ابی صالح نے اپنے والد ابو صالح سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ جس نے ہمارے خلاف ہتھیار اٹھایا ، وہ ہم میں سے نہیں اور جس نے ہمیں دھوکا دیا ، وہ ہم میں سے نہیں ۔ ‘‘"],"14118":["bukhari",7070,"ہم سے عبداللہ بن یوسف نے بیان کیا، انہیں امام مالک نے خبر دی، انہیں نافع نے اور انہیں عبداللہ بن عمر رضی اللہ عنہما نے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا جس نے ہم مسلمانوں پر ہتھیار اٹھایا وہ ہم سے نہیں ہے۔"],"14119":["bukhari",7071,"ہم سے محمد بن العلاء نے بیان کیا، کہا ہم سے ابواسامہ نے بیان کیا، ان سے برید نے، ان سے ابوبردہ نے اور ان سے ابوموسیٰ رضی اللہ عنہ نے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا جس نے ہم مسلمانوں پر ہتھیار اٹھایا وہ ہم سے نہیں ہے۔"],"14120":["muslim",200,"ایاس بن سلمہ نے اپنے والد سے ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، آپ صلی اللہ علیہ وسلم نے فرمایا : ’’ جس نےہم پر تلوار سونتی ، وہ ہم میں سے نہیں ۔ ‘‘"],"14121":["bukhari",7075,"ہم سے محمد بن العلاء نے بیان کیا، کہا ہم سے ابواسامہ نے بیان کیا، ان سے برید نے، ان سے ابوبردہ نے اور ان سے ابوموسیٰ رضی اللہ عنہ نے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا جب تم میں سے کوئی ہماری مسجد میں یا ہمارے بازار میں گزرے اور اس کے پاس تیر ہوں تو اسے چاہئیے کہ اس کی نوک کا خیال رکھے۔ یا آپ صلی اللہ علیہ وسلم نے فرمایا کہ اپنے ہاتھ سے انہیں تھامے رہے۔ کہیں کسی مسلمان کو اس سے کوئی تکلیف نہ پہنچے۔ 8- بَابُ قَوْلِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «لاَ تَرْجِعُوا بَعْدِي كُفَّارًا، يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ»:"],"14122":["muslim",6708,"ثابت نے ابوبردہ سے ، انہوں نے سیدنا ابوموسی رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" جب تم میں سے کوئی شخص مجلس یا بازار میں سے گزرے اور اس کے ہاتھ میں تیر ہوں تو وہ انہیں ان کے پیکانوں ( نوکدار حصوں ) سے پکڑے ، پھر ( تنبیہ ہے ) ان کے نوکیلے حصے کی طرف سے پکڑے ، پھر ( تاکید ہے ) ان کے نوکیلے حصوں کی طرف سے پکڑے ۔ \"\" کہا : تو سیدنا ابوموسی رضی اللہ عنہ نے کہا : اللہ کی قسم! ( ہمارا یہ حال ہے کہ ) ہم نے مرنے سے پہلے ( اپنی اسی زندگی میں ) ان تیروں کو ایک دوسرے کے چہروں کی طرف سیدھا کر لیا ہے ۔"],"14123":["bukhari",7073,"ہم سے علی بن عبداللہ مدینی نے بیان کیا، کہا ہم سے سفیان بن عیینہ نے بیان کیا، کہا کہ میں نے عمرو بن دینار سے کہا ابو محمد! تم نے جابر بن عبداللہ رضی اللہ عنہما سے سنا ہے کہ انہوں نے بیان کیا کہ ایک صاحب تیر لے کر مسجد میں سے گزرے تو ان سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ تیر کی نوک کا خیال رکھو۔ عمرو نے کہا جی ہاں میں نے سنا ہے۔"],"14124":["muslim",6705,"سفیان بن عیینہ نے عمرو ( بن دینار ) سے روایت کی ، انہوں نے سیدنا جابر رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : ایک شخص چند تیر لے کر مسجد میں سے گزرا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ان تیروں کو ان کی نوکوں ( کی طرف سے ) پکڑو ۔"],"14128":["abudawud",5004,"عبدالرحمٰن بن ابی لیلی سے روایت ہے کہ ہم سے صحابہ کرام رضی اللہ عنہم نے بیان کیا کہ وہ لوگ نبی اکرم صلی اللہ علیہ وسلم کے ساتھ جا رہے تھے، ان میں سے ایک صاحب سو گئے، کچھ لوگ اس رسی کے پاس گئے، جو اس کے پاس تھی اور اسے لے لیا تو وہ ڈر گیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمان کے لیے درست نہیں کہ وہ کسی مسلمان کو ڈرائے\"۔"],"14129":["tirmidhi",1931,"ابو الدرداء رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص اپنے بھائی کی عزت (اس کی غیر موجودگی میں) بچائے اللہ تعالیٰ قیامت کے دن اس کے چہرے کو جہنم سے بچائے گا\"۔"],"14131":["muslim",6909,"ابومعاویہ نے اعمش سے ، انہوں نے ابوصالح سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس شخص نے کسی مسلمان کی دنیاوی تکلیفوں میں سے کوئی تکلیف دور کی ، اللہ تعالی اس کی قیامت کی تکلیفوں میں سے کوئی تکلیف دور کرے گا اور جس شخص نے کسی تنگ دست کے لیے آسانی کی ، اللہ تعالی اس کے لیے دنیا اور آخرت میں آسانی کرے گا اور جس نے کسی مسلمان کی پردہ پوشی کی ، اللہ تعالی دنیا اور آخرت میں اس کی پردہ پشی کرے گا اور اللہ تعالی اس وقت تک بندے کی مدد میں لگا رہتا ہے جب تک بندہ اپنے بھائی کی مدد میں لگا رہتا ہے اور جو شخص اس راستے پر چلتا ہے جس میں وہ علم حاصل کرنا چاہتا ہے تو اللہ تعالی اس کے ذریعے سے اس کے لیے جنت کا راستہ آسان کر دیتا ہے ، اللہ کے گھروں میں سے کسی گھر میں لوگوں کا کوئی گروہ اکٹھا نہیں ہوتا ، وہ قرآن کی تلاوت کرتے ہیں اور اس کا درس و تدریس کرتے ہیں مگر ان پر سکینت ( اطمینان و سکون قلب ) کا نزول ہوتا ہے اور ( اللہ کی ) رحمت ان کو ڈھانپ لیتی ہے اور فرشتے ان کو اپنے گھیرے میں لے لیتے ہیں اور اللہ تعالی اپنے مقربین میں جو اس کے پاس ہوتے ہیں ان کا ذکر کرتا ہے اور جس کے عمل نے اسے ( خیر کے حصول میں ) پیچھے رکھا ، اس کا نسب اسے تیز نہیں کر سکتا ۔"],"14132":["tirmidhi",2484,"حصین کہتے ہیں کہ ایک سائل نے آ کر ابن عباس رضی اللہ عنہما سے کچھ مانگا تو ابن عباس نے سائل سے کہا: کیا تم یہ گواہی دیتے ہو کہ اللہ تعالیٰ کے سوا کوئی معبود برحق نہیں ہے؟ اس نے کہا: ہاں، آپ نے کہا: کیا تم یہ گواہی دیتے ہو کہ محمد صلی اللہ علیہ وسلم اللہ کے رسول ہیں؟ اس نے کہا: ہاں، آپ نے کہا: کیا تم رمضان کے روزے رکھتے ہو؟ اس نے کہا: ہاں، آپ نے کہا: تم نے سوال کیا اور سائل کا حق ہوتا ہے، بیشک ہمارے اوپر ضروری ہے کہ ہم تمہارے ساتھ حسن سلوک کریں، چنانچہ انہوں نے اسے ایک کپڑا دیا اور کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا ہے: \"جو کوئی مسلمان کسی مسلمان بھائی کو کوئی کپڑا پہناتا ہے تو وہ اللہ کی امان میں اس وقت تک رہتا ہے جب تک اس کپڑے کا ایک ٹکڑا بھی اس پر باقی رہتا ہے\"۔"],"14133":["abudawud",4876,"سعید بن زید رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"سب سے بڑی زیادتی یہ ہے کہ آدمی ناحق کسی مسلمان کی بے عزتی کرے\"۔"],"14134":["abudawud",4877,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بڑے گناہوں میں سب سے بڑا گناہ یہ ہے کہ آدمی ناحق کسی مسلمان کی بے عزتی میں زبان دراز کرے، اور یہ بھی کبیرہ گناہوں میں سے ہے کہ ایک گالی کے بدلے دو گالیاں دی جائیں\"۔"],"14136":["bukhari",6133,"ہم سے قتیبہ بن سعید نے بیان کیا، انہوں نے کہا ہم سے لیث بن سعد نے بیان کیا، انہوں نے کہا ان سے عقیل نے بیان کیا، ان سے زہری نے، ان سے ابن مسیب نے اور ان سے ابوہریرہ رضی اللہ عنہ نے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا مومن کو ایک سوراخ سے دوبارہ ڈنگ نہیں لگ سکتا۔"],"14139":["bukhari",1239,"ہم سے ابوالولید نے بیان کیا، کہا کہ ہم سے شعبہ نے بیان کیا، ان سے اشعث بن ابی الثعثاء نے، انہوں نے کہا کہ میں نے معاویہ بن سوید مقرن سے سنا، وہ براء بن عازب رضی اللہ عنہ سے نقل کرتے تھے کہ ہمیں نبی کریم صلی اللہ علیہ وسلم نے سات کاموں کا حکم دیا اور سات کاموں سے روکا۔ ہمیں آپ صلی اللہ علیہ وسلم نے حکم دیا تھا جنازہ کے ساتھ چلنے، مریض کی مزاج پرسی، دعوت قبول کرنے، مظلوم کی مدد کرنے کا، قسم پوری کرنے کا، سلام کا جواب دینے کا، چھینک پر «يرحمک الله» کہنے کا اور آپ صلی اللہ علیہ وسلم نے ہمیں منع کیا تھا چاندی کے برتن (استعمال میں لانے) سے، سونے کی انگوٹھی پہننے سے، ریشم اور دیباج (کے کپڑوں کے پہننے) سے، قسی سے، استبرق سے۔"],"14140":["bukhari",6224,"ہم سے مالک بن اسماعیل نے بیان کیا، انہوں نے کہا ہم سے عبدالعزیز بن ابی سلمہ نے بیان کیا، انہیں عبداللہ بن دینار نے خبر دی، وہ ابوصالح سے اور وہ ابوہریرہ رضی اللہ عنہ سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا جب تم میں سے کوئی چھینکے تو«الحمد الله» کہے اور اس کا بھائی یا اس کا ساتھی (راوی کو شبہ تھا) «يرحمك الله» کہے۔ جب ساتھی «يرحمك الله» کہے تو اس کے جواب میں چھینکنے والا «يهديكم الله ويصلح بالكم» ۔"],"14141":["bukhari",6221,"ہم سے محمد بن کثیر نے بیان کیا، کہا ہم سے سفیان ثوری نے بیان کیا، کہا ہم سے سفیان نے بیان کیا اور ان سے انس بن مالک رضی اللہ عنہ نے بیان کیا کہ نبی کریم صلی اللہ علیہ وسلم کے پاس دو اصحاب چھینکے۔ نبی کریم صلی اللہ علیہ وسلم نے ایک کا جواب یرحمک اللہ (اللہ تم پر رحم کرے) سے دیا اور دوسرے کا نہیں۔ نبی کریم صلی اللہ علیہ وسلم سے اس کی وجہ پوچھی گئی تو فرمایا کہ اس نے الحمدللہ کہا تھا(اس لیے اس کا جواب دیا) اور دوسرے نے الحمدللہ نہیں کہا تھا۔ چھینکنے والے کو الحمدللہ ضرور کہنا چاہئے اور سننے والوں کو یرحمک اللہ۔"],"14142":["muslim",7544,"ابو بردہ سے روایت ہے کہا : میں ( اپنے والد ) سیدنا ابو موسی رضی اللہ تعالی عنہ کے پاس گیا وہ اس وقت سیدنا فضل بن عباس رضی اللہ تعالی عنہ کی بیٹی کے گھر تھے ۔ مجھے چھینک آئی تو انھوں نے جواب میں دعا نہیں دی اور اس ( فضل رضی اللہ تعالی عنہ کی بیٹی ) کو چھینک آئی تو اس کو انھوں نے جواب میں دعا دی میں اپنی والدہ کے پاس گیا اور انھیں بتا یا جب وہ ( میرے والد ) ان ( میری والدہ ) کے پاس آئے تو انھوں نے کہا : تمھارے پاس میرے بیٹے کو چھینک آئی تو تم نے جواب میں دعا نہیں دی ۔ اور ان ( فضل بن عباس رضی اللہ تعالی عنہ کی بیٹی ) کو چھینک آئی تو تم نے جواب میں دعا دی ۔ انھوں نے کہا : تمھارے بیٹے کو چھینک آئی تو اس نے الحمد اللہ نہیں کہا : اس لیے میں نے جواب نہیں دیا اس ( خاتون ) کو چھینک آئی تو انھوں نے الحمد اللہ کہا : اس لیے میں نےان کو جواب میں دعا دی ۔ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا : آپ فرماتے تھے : \" جب تم میں سے کسی کو چھینک آئے اور وہ الحمد اللہ کہے تو اس کو جواب میں دعا دواور اگر وہ الحمد اللہ نہ کہے تو دعا نہ دو ۔"],"14144":["muslim",7545,"ایاس بن سلمہ بن اکوع نے مجھے حدیث بیان کی کہ ان کے والد نے ان سے حدیث بیان کی ، انھوں نے نبی صلی اللہ علیہ وسلم سے سنا : آپ کے پاس ایک شخص کو چھینک آئی تو آپ نے اسے دعا دی «يَرْحَمُكَ اللَّهُ» اللہ تم پر رحم فرمائے ۔ \" اسے دوسری چھینک آئی تو آپ نے فرمایا \" اس شخص کو زکام ہے ۔"],"14145":["abudawud",5029,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کو جب چھینک آتی تھی تو اپنا ہاتھ یا اپنا کپڑا منہ پر رکھ لیتے اور آہستہ آواز سے چھینکتے۔"],"14146":["bukhari",6226,"ہم سے عاصم بن علی نے بیان کیا، انہوں نے کہا ہم سے ابن ابی ذئب نے بیان کیا، انہوں نے کہا کہ ہم سے سعید مقبری نے بیان کیا، ان سے ان کے والد نے بیان کیا، ان سے ابوہریرہ رضی اللہ عنہ نے بیان کیا اور ان سے نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ اللہ تعالیٰ چھینک کو پسند کرتا ہے کیونکہ وہ بعض دفعہ صحت کی علامت ہے اور جمائی کو ناپسند کرتا ہے۔ اس لیے جب تم میں سے کوئی شخص چھینکے تو وہ الحمدللہ کہے لیکن جمائی لینا شیطان کی طرف سے ہوتا ہے۔ اس لیے جب تم میں سے کسی کو جمائی آئے تو وہ اپنی قوت و طاقت کے مطابق اسے روکے۔ اس لیے کہ جب تم میں سے کوئی جمائی لیتا ہے تو شیطان ہنستا ہے۔"],"14147":["muslim",7546,"سیدنا ابو ہریرہ رضی اللہ تعالی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جما ئی شیطان کی طرف سے ہے لہٰذاتم میں سے جب کسی شخص کو جمائی آئے تو وہ جہاں تک اس کو روک سکے روکے ۔"],"14148":["muslim",7547,"بشر بن مفضل نے کہا : ہمیں سہیل بن ابی صالح نے حدیث بیان کی انھوں نے کہا : میں نے ابو سعید خدری رضی اللہ تعالی عنہ کے بیٹے ( عبدالرحمان ) سے سنا وہ میرے والد کو اپنے والد سے حدیث بیان کر رہے تھے انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب تم میں سے کسی شخص کو جمائی آئے تو وہ اپنے منہ پر ہاتھ رکھ کر اس کو روکے کیونکہ ( ایسا نہ کرنے سے ) شیطان اندر داخل ہو تا ہے ۔"],"14149":["bukhari",5304,"ہم سے عمرو بن زرارہ نے بیان کیا، کہا کہ ہم کو عبدالعزیز بن ابی حازم نے خبر دی، انہیں ان کے والد نے اور ان سے سہل رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ میں اور یتیم کی پرورش کرنے والا جنت میں اس طرح ہوں گے اور آپ نے شہادت کی انگلی اور بیچ کی انگلی سے اشارہ کیا اور ان دونوں انگلیوں کے درمیان تھوڑی سی جگہ کھلی رکھی۔"],"14150":["muslim",7525,"اسحٰق بن عیسی نے کہا : ہمیں امام مالک رحمۃ اللہ علیہ نے ثور بن یزید سے حدیث بیان کی انھوں نے کہا : میں نے ابو غیث کو سیدنا ابو ہریرہ رضی اللہ تعالی عنہ سے حدیث بیان کرتے ہوئے سنا انھوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" یتیم کی پرورش کرنے والا اس کا اپنا ( رشتہ دار ) ہو یا غیر ہو میں اور وہ جنت میں اس طرح ہوں گے ۔ \" پھر امام مالک رحمۃ اللہ علیہ نے انگشت شہادت اور درمیان انگلی ( کو ملاکر اس ) کے ساتھ اشارہ کیا ۔"],"14151":["bukhari",5353,"ہم سے یحیی بن قزعہ نے بیان کیا، کہا ہم سے امام مالک نے بیان کیا، ان سے ثور بن زید نے، ان سے ابوالغیث (سالم) نے اور ان سے ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ بیواؤں اور مسکینوں کے کام آنے والا اللہ کے راستے میں جہاد کرنے والے کے برابر ہے، یا رات بھر عبادت اور دن کو روزے رکھنے والے کے برابر ہے۔"],"14152":["muslim",7529,"یزید بن ہارون نے ہمیں حدیث بیان کی ، کہا : ہمیں عبد العزیز بن ابو سلمہ نے وہب بن کیسان سے خبر دی انھوں نے عبید بن عمیر لیثی سے انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالی عنہ سے اور نھوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" ایک دفعہ ایک شخص زمین میں ایک صحرائی ٹکڑے پر کھڑا تھا ۔ اس نے ایک بادل میں آوازسنی : \" فلاں کے باغ کو سیراب کرو ۔ \" وہ بادل ایک جانب بنا اور ایک پتھریلی زمین میں اپنا پانی انڈیل دیا ۔ پانی کے بہاؤوالی ندیوں میں سے ایک ندی نے وہ سارا پانی اپنے اندر لے لیا ۔ وہ شخص پانی کے پیچھے پیچھے چل پڑا تو وہاں ایک آدمی اپنے باغ میں کھڑا اپنے کدال سے پانی کا رخ ( اپنے باغ کی طرف ) پھیر رہا ہے ۔ اس نے اس سے کہا : اللہ کےبندے !تمھارا نام کیا ہے؟اس نے کہا : فلاں وہی نام جو اس نے بادل میں سنا تھا ۔ اس ( آدمی ) نے اس سے کہا : اللہ کے بندے!تم نے مجھ سے میرا نام کیوں پوچھا ہے؟اس نے کہا : میں نے اس بادل میں جس کا یہ پانی ہے ( کسی کو ) یہ کہتے سناتھا ۔ فلاں کے باغ کو سیراب کرو تمھارا نام لیا تھا ۔ تم اس میں کیا کرتے ہو ۔ \" اس نے جواب دیا تم نے یہ بات کہہ دی ہے تو میں ( تمھیں بتادیتا ہوں ) اس باغ سے جو کچھ حاصل ہوتا ہے میں اس پر نظر ڈال کر اس کا ایک تہائی حصہ صدقہ کردیتا ہوں ایک تہائی میں اور میرے گھروالے کھاتے ہیں ۔ اور ایک تہائی اسی ( باغ کی دیکھ بھال ) میں لگا دیتا ہوں ۔"],"14153":["ibnmajah",3678,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اے اللہ! میں دو کمزوروں ایک یتیم اور ایک عورت کا حق مارنے کو حرام قرار دیتا ہوں\"۔"],"14155":["abudawud",4943,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو ہمارے چھوٹے پر رحم نہ کھائے اور ہمارے بڑے کا حق نہ پہنچانے (اس کا ادب و احترام نہ کرے) تو وہ ہم میں سے نہیں\"۔"],"14157":["bukhari",6014,"ہم سے اسماعیل بن ابی اویس نے بیان کیا، کہا کہ مجھ سے امام مالک نے بیان کیا، ان سے یحیی بن سعید نے کہا کہ مجھے ابوبکر بن محمد نے خبر دی، انہیں عمرہ نے اور انہیں عائشہ رضی اللہ عنہا نے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا جبرائیل علیہ السلام مجھے پڑوسی کے بارے میں باربار اس طرح وصیت کرتے رہے کہ مجھے خیال گزرا کہ شاید پڑوسی کو وراثت میں شریک نہ کر دیں۔"],"14158":["bukhari",6015,"ہم سے محمد بن منہال نے بیان کیا، کہا ہم سے یزید بن زریع نے بیان کیا، ان سے عمر بن محمد نے، ان سے ان کے والد نے اور ان سے ابن عمر رضی اللہ عنہما نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا جبرائیل علیہ السلام مجھے اس طرح باربار پڑوسی کے حق میں وصیت کرتے رہے کہ مجھے خیال گزرا کہ شاید پڑوسی کو وراثت میں شریک نہ کر دیں۔"],"14159":["ibnmajah",3674,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جبرائیل برابر پڑوسی کے بارے میں وصیت و تلقین کرتے رہے، یہاں تک کہ مجھے یہ خیال ہونے لگا کہ وہ ہمسایہ کو وارث بنا دیں گے\"۔"],"14162":["muslim",285,"ابو اشہب نے حسن ( بصری ) سے حدیث بیان کی ، انہوں نے کہا : عبید اللہ بن زیاد نےسیدنا معقل بن یسار مزنی رضی اللہ عنہ کے مرض ا لموت میں ان کی عیادت کی تو معقل رضی اللہ عنہ نے اس سے کہا : میں تمہیں ایک حدیث سنانے لگا ہوں جو میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنی ۔ اگر میں جانتا کہ میں ا بھی اور زندہ رہوں گا تو تمہیں یہ حدیث نہ سناتا ۔ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا : ’’ کوئی ایسا بندہ جسے اللہ کسی رعایا کا نگران بناتا ہے اور مرنے کے دن وہ اس حالت میں مرتا ہے کہ اپنی رعیت سے دھوکا کرنے والا ہے تو اللہ اس پر جنت حرام کر دیتا ہے ۔ ‘‘"],"14163":["tirmidhi",1944,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کے نزدیک سب سے بہتر دوست وہ ہے جو لوگوں میں اپنے دوست کے لیے بہتر ہے، اور اللہ کے نزدیک سب سے بہتر پڑوسی وہ ہے جو اپنے پڑوسی کے لیے بہتر ہے\"۔"],"14165":["abudawud",5152,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ انہوں نے ایک بکری ذبح کی تو (گھر والوں) سے کہا: کیا تم لوگوں نے میرے یہودی پڑوسی کو ہدیہ بھیجا (نہ بھیجا ہو تو بھیج دو) میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے آپ فرماتے تھے: \"جبرائیل مجھے برابر پڑوسی، کے ساتھ حسن سلوک کی وصیت فرماتے رہے یہاں تک کہ مجھے گمان گزرا کہ وہ اسے وارث بنا دیں گے\"۔"],"14166":["bukhari",6017,"ہم سے عبداللہ بن یوسف نے بیان کیا، کہا ہم سے لیث نے بیان کیا، کہا ہم سے سعید نے بیان کیا وہ سعید مقبری ہیں، ان سے ان کے والد نے اور ان سے ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ نبی کریم صلی اللہ علیہ وسلم فرمایا کرتے تھے اے مسلمان عورتو! تم میں سے کوئی عورت اپنی کسی پڑوسن کے لیے کسی بھی چیز کو (ہدیہ میں) دینے کے لیے حقیر نہ سمجھے خواہ بکری کا پایہ ہی کیوں نہ ہو۔"],"14167":["bukhari",6020,"ہم سے حجاج بن منہال نے بیان کیا، کہا ہم سے شعبہ نے بیان کیا، کہا کہ مجھے ابوعمران نے خبر دی، کہا کہ میں نے طلحہ سے سنا اور ان سے عائشہ رضی اللہ عنہا نے بیان کیا کہ میں نے عرض کیا: یا رسول اللہ! میری پڑوسنیں ہیں (اگر ہدیہ ایک ہو تو) میں ان میں سے کس کے پاس ہدیہ بھیجوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا جس کا دروازہ تم سے (تمہارے دروازے سے) زیادہ قریب ہو۔"],"14168":["bukhari",6018,"ہم سے قتیبہ بن سعید نے بیان کیا، انہوں نے کہا ہم سے ابوالاحوص نے بیان، ان سے ابوحصین نے، ان سے ابوصالح نے اور ان سے ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا جو کوئی اللہ اور آخرت کے دن پر ایمان رکھتا ہو وہ اپنے پڑوسی کو تکلیف نہ پہنچائے اور جو کوئی اللہ اور آخرت کے دن پر ایمان رکھتا ہو وہ اپنے مہمان کی عزت کرے اور جو کوئی اللہ اور آخرت کے دن پر ایمان رکھتا ہو وہ اچھی بات زبان سے نکالے ورنہ خاموش رہے۔"],"14169":["bukhari",6019,"ہم سے عبداللہ بن یوسف نے بیان کیا، انہوں نے کہا ہم سے لیث بن سعد نے بیان کیا، انہوں نے کہا کہ مجھ سے سعید مقبری نے بیان کیا، ان سے ابوشریح عدوی رضی اللہ عنہ نے بیان کیا انہوں نے کہا کہ میرے کانوں نے سنا اور میری آنکھوں نے دیکھا جب رسول اللہ صلی اللہ علیہ وسلم گفتگو فرما رہے تھے۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ جو شخص اللہ اور آخرت کے دن پر ایمان رکھتا ہو وہ اپنے پڑوسی کا اکرام کرے اور جو شخص اللہ اور آخرت کے دن پر ایمان رکھتا ہو وہ اپنے مہمان کی دستور کے موافق ہر طرح سے عزت کرے۔ پوچھا: یا رسول اللہ! دستور کے موافق کب تک ہے۔ فرمایا ایک دن اور ایک رات اور میزبانی تین دن کی ہے اور جو اس کے بعد ہو وہ اس کے لیے صدقہ ہے اور جو اللہ اور آخرت کے دن پر ایمان رکھتا ہو وہ بہتر بات کہے یا خاموش رہے۔"],"14173":["abudawud",5153,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ ایک شخص نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، اپنے پڑوسی کی شکایت کر رہا تھا، آپ نے فرمایا:\"جاؤ صبر کرو\" پھر وہ آپ کے پاس دوسری یا تیسری دفعہ آیا، تو آپ نے فرمایا: \"جاؤ اپنا سامان نکال کر راستے میں ڈھیر کر دو\" تو اس نے اپنا سامان نکال کر راستہ میں ڈال دیا، لوگ اس سے وجہ پوچھنے لگے اور وہ پڑوسی کے متعلق لوگوں کو بتانے لگا، لوگ (سن کر) اس پر لعنت کرنے اور اسے بد دعا دینے لگے کہ اللہ اس کے ساتھ ایسا کرے، ایسا کرے، اس پر اس کا پڑوسی آیا اور کہنے لگا: اب آپ (گھر میں) واپس آ جائے آئندہ مجھ سے کوئی ایسی بات نہ دیکھیں گے جو آپ کو ناپسند ہو۔"],"14176":["bukhari",6016,"ہم سے عاصم بن علی نے بیان کیا، انہوں نے کہا ہم سے ابن ابی ذئب نے بیان کیا، ان سے سعید نے بیان کیا، ان سے ابوشریح نے بیان کیا اور ان سے نبی کریم صلی اللہ علیہ وسلم نے بیان کیا واللہ! وہ ایمان والا نہیں۔ واللہ! وہ ایمان والا نہیں۔ واللہ! وہ ایمان والا نہیں۔ عرض کیا گیا کون: یا رسول اللہ؟ فرمایا وہ جس کے شر سے اس کا پڑوسی محفوظ نہ ہو۔ اس حدیث کو شبابہ اور اسد بن موسیٰ نے بھی روایت کیا ہے اور حمید بن اسود اور عثمان بن عمر اور ابوبکر بن عیاش اور شعیب بن اسحاق نے اس حدیث کو ابن ابی ذئب سے یوں روایت کیا ہے، انہوں نے مقبری سے، انہوں نے ابوہریرہ رضی اللہ عنہ سے۔"],"14178":["muslim",90,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ جس کی ایذا رسانی سے اس کے پڑوسی محفوظ نہ ہوں ، وہ جنت میں نہیں جائے گا ۔ ‘‘"],"14180":["bukhari",2463,"ہم سے عبداللہ بن مسلمہ نے بیان کیا، کہا ہم سے امام مالک رحمہ اللہ نے، ان سے ابن شہاب نے، ان سے اعرج نے، اور ان سے ابوہریرہ رضی اللہ عنہ نے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، کوئی شخص اپنے پڑوسی کو اپنی دیوار میں کھونٹی گاڑنے سے نہ روکے۔ پھر ابوہریرہ رضی اللہ عنہ کہا کرتے تھے، یہ کیا بات ہے کہ میں تمہیں اس سے منہ پھیرنے والا پاتا ہوں۔ قسم اللہ! اس کھونٹی کو تمہارے کندھوں کے درمیان گاڑ دوں گا۔"],"14184":["bukhari",6228,"ہم سے ابوالیمان نے بیان کیا، انہوں نے کہا ہم کو شعیب نے خبر دی، ان سے زہری نے بیان کیا، انہیں سلیمان بن یسار نے خبر دی اور انہیں عبداللہ بن عباس رضی اللہ عنہما نے خبر دی، انہوں نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فضل بن عباس رضی اللہ عنہما کو قربانی کے دن اپنی سواری پر اپنے پیچھے بٹھایا۔ وہ خوبصورت گورے مرد تھے۔ نبی کریم صلی اللہ علیہ وسلم لوگوں کو مسائل بتانے کے لیے کھڑے ہو گئے۔ اسی دوران میں قبیلہ خثعم کی ایک خوبصورت عورت بھی نبی کریم صلی اللہ علیہ وسلم سے مسئلہ پوچھنے آئی۔ فضل بھی اس عورت کو دیکھنے لگے۔ اس کا حسن و جمال ان کو بھلا معلوم ہوا۔ نبی کریم صلی اللہ علیہ وسلم نے مڑ کر دیکھا تو فضل اسے دیکھ رہے تھے۔ نبی کریم صلی اللہ علیہ وسلم نے اپنا ہاتھ پیچھے لے جا کر فضل کی ٹھوڑی پکڑی اور ان کا چہرہ دوسری طرف کر دیا۔ پھر اس عورت نے کہا: یا رسول اللہ! حج کے بارے میں اللہ کا جو اپنے بندوں پر فریضہ ہے وہ میرے والد پر لاگو ہوتا ہے، جو بہت بوڑھے ہو چکے ہیں اور سواری پر سیدھے نہیں بیٹھ سکتے۔ کیا اگر میں ان کی طرف سے حج کر لوں تو ان کا حج ادا ہو جائے گا؟ نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ ہاں ہو جائے گا۔"],"14185":["bukhari",6243,"ہم سے حمیدی نے بیان کیا، کہا ہم سے سفیان نے بیان کیا، ان سے ابن طاؤس نے، ان سے ان کے والد نے اور ان سے ابن عباس رضی اللہ عنہما نے بیان کیا کہ ابوہریرہ رضی اللہ عنہ کی حدیث سے زیادہ صغیرہ گناہوں سے مشابہ میں نے اور کوئی چیز نہیں دیکھی۔(ابوہریرہ رضی اللہ عنہ نے جو باتیں بیان کی ہیں وہ مراد ہیں)۔ مجھ سے محمود نے بیان کیا، کہا ہم سے عبدالرزاق نے خبر دی، کہا ہم کو معمر نے خبر دی، انہیں ابن طاؤس نے، انہیں ان کے والد نے اور ان سے ابن عباس رضی اللہ عنہما نے کہ میں نے کوئی چیز صغیرہ گناہوں سے مشابہ اس حدیث کے مقابلہ میں نہیں دیکھی جسے ابوہریرہ رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم سے نقل کیا ہے کہ اللہ تعالیٰ نے انسانوں کے معاملہ میں زنا میں سے اس کا حصہ لکھ دیا ہے جس سے وہ لامحالہ دوچار ہو گا پس آنکھ کا زنا دیکھنا ہے، زبان کا زنا بولنا ہے، دل کا زنا یہ ہے کہ وہ خواہش اور آرزو کرتا ہے پھر شرمگاہ اس خواہش کو سچا کرتی ہے یا جھٹلا دیتی ہے۔"],"14186":["muslim",5660,"یزید بن زریع ، اسماعیل بن علیہ اور ہشیم نے یو نس سے ، انھوں نے عمرو بن سعید سے ، انھوں نے ابوزرعہ سے ، انھوں نے سیدنا جریر بن عبد اللہ رضی اللہ تعالی عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم سے اچانک نظر پڑجا نے کے بارے میں پو چھا تو آپ نے مجھے حکم دیا کہ میں اپنی نظر ہٹا لوں ۔"],"14188":["bukhari",6241,"ہم سے علی بن عبداللہ نے بیان کیا، کہا ہم سے سفیان نے، ان سے زہری نے بیان کیا (سفیان نے کہا کہ) میں نے یہ حدیث زہری سے سن کر اس طرح یاد کی ہے کہ جیسے تو اس وقت یہاں موجود ہو اور ان سے سہل بن سعد نے کہ ایک شخص نے نبی کریم صلی اللہ علیہ وسلم کے کسی حجرہ میں سوراخ سے دیکھا، نبی کریم صلی اللہ علیہ وسلم کے پاس اس وقت ایک کنگھا تھا جس سے آپ سر مبارک کھجا رہے تھے۔ نبی کریم صلی اللہ علیہ وسلم نے اس سے فرمایا کہ اگر مجھے معلوم ہوتا کہ تم جھانک رہے ہو تو یہ کنگھا تمہاری آنکھ میں چبھو دیتا(اندر داخل ہونے سے پہلے) اجازت مانگنا تو ہے ہی اس لیے کہ (اندر کی کوئی ذاتی چیز) نہ دیکھی جائے۔"],"14189":["bukhari",6242,"ہم سے مسدد نے بیان کیا، کہا ہم سے حماد بن زید نے بیان کیا، ان سے عبیداللہ بن ابی بکر نے اور ان سے انس بن مالک رضی اللہ عنہ نے کہ ایک صاحب نبی کریم صلی اللہ علیہ وسلم کے کسی حجرہ میں جھانک کر دیکھنے لگے تو نبی کریم صلی اللہ علیہ وسلم ان کی طرف تیر کا پھل یا بہت سے پھل لے کر بڑھے، گویا میں نبی کریم صلی اللہ علیہ وسلم کو دیکھ رہا ہوں ان صاحب کی طرف اس طرح چپکے چپکے تشریف لائے۔"],"14190":["bukhari",6902,"ہم سے علی بن عبداللہ نے بیان کیا، کہا ہم سے سفیان نے بیان کیا، ان سے ابوالزناد نے، ان سے اعرج نے، ان سے ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ ابوالقاسم صلی اللہ علیہ وسلم نے فرمایا اگر کوئی شخص تمہاری اجازت کے بغیر تمہیں (جب کہ تم گھر کے اندر ہو)جھانک کر دیکھے اور تم اسے کنکری مار دو جس سے اس کی آنکھ پھوٹ جائے تو تم پر کوئی گناہ نہیں ہے۔"],"14191":["muslim",5658,"سہیل کے والد ابو صالح نے سیدنا ابو ہریرہ رضی اللہ تعالی عنہ سے ، انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فر ما یا : \" جس نے اجازت کے بغیر لو گوں کے گھر میں تانک جھانک کی ، انھیں اجا زت ہے کہ وہ اس کی آنکھ پھوڑدیں ۔"],"14192":["abudawud",5174,"ہزیل کہتے ہیں کہ ایک شخص رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، (عثمان کی روایت میں ہے کہ وہ سعد بن ابی وقاص تھے) تو وہ نبی اکرم صلی اللہ علیہ وسلم کے دروازے پر اجازت طلب کرنے کے لیے رکے اور دروازے پر یا دروازے کی طرف منہ کر کے کھڑے ہو گئے، تو نبی اکرم صلی اللہ علیہ وسلم نے ان سے فرمایا: تمہیں اس طرح کھڑا ہونا چاہیئے یا اس طرح؟ (یعنی دروازہ سے ہٹ کر) کیونکہ اجازت کا مقصود نظر ہی کی اجازت ہے۔"],"14193":["abudawud",5173,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب نگاہ اندر پہنچ گئی تو پھر اجازت کا کوئی مطلب ہی نہیں\"۔"],"14194":["bukhari",6244,"ہم سے اسحٰق نے بیان کیا کہا ہم کو عبدالصمد نے خبر دی، انہیں عبداللہ بن مثنی نے خبر دی ان سے ثمامہ بن عبداللہ نے بیان کیا اور ان سے انس رضی اللہ عنہ نے کہ رسول اللہ صلی اللہ علیہ وسلم جب کسی کو سلام کرتے (اور جواب نہ ملتا) تو تین مرتبہ سلام کرتے تھے اور جب آپ صلی اللہ علیہ وسلم کوئی بات فرماتے تو (زیادہ سے زیادہ) تین مرتبہ اسے دہراتے۔"],"14195":["bukhari",6245,"ہم سے علی بن عبداللہ نے بیان کیا، کہا ہم سے سفیان نے بیان کیا، کہا ہم سے یزید بن خصیفہ نے بیان کیا ان سے بسر بن سعید اور ان سے ابو سعید خدری رضی اللہ عنہ نے بیان کیا کہ میں انصار کی ایک مجلس میں تھا کہ ابوموسیٰ رضی اللہ عنہ تشریف لائے جیسے گھبرائے ہوئے ہوں۔ انہوں نے کہا کہ میں نے عمر رضی اللہ عنہ کے یہاں تین مرتبہ اندر آنے کی اجازت چاہی لیکن مجھے کوئی جواب نہیں ملا، اس لیے واپس چلا آیا (عمر رضی اللہ عنہ کو معلوم ہوا) تو انہوں نے دریافت کیا کہ (اندر آنے میں) کیا بات مانع تھی؟ میں نے کہا کہ میں نے تین مرتبہ اندر آنے کی اجازت مانگی اور جب مجھے کوئی جواب نہیں ملا تو واپس چلا گیا اور رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے کہ جب تم میں سے کوئی کسی سے تین مرتبہ اجازت چاہے اور اجازت نہ ملے تو واپس چلا جانا چاہئے۔ عمر رضی اللہ عنہ نے کہا: واللہ! تمہیں اس حدیث کی صحت کے لیے کوئی گواہ لانا ہو گا۔ (ابوموسیٰ رضی اللہ عنہ نے مجلس والوں سے پوچھا) کیا تم میں کوئی ایسا ہے جس نے نبی کریم صلی اللہ علیہ وسلم سے یہ حدیث سنی ہو؟ ابی بن کعب رضی اللہ عنہ نے کہا کہ اللہ کی قسم! تمہارے ساتھ (اس کی گواہی دینے کے سوا) جماعت میں سب سے کم عمر شخص کے کوئی اور نہیں کھڑا ہو گا۔ ابوسعید نے کہا اور میں ہی جماعت کا وہ سب سے کم عمر آدمی تھا میں ان کے ساتھ اٹھ کھڑا ہو گیا اور عمر رضی اللہ عنہ سے کہا کہ واقعی نبی کریم صلی اللہ علیہ وسلم نے ایسا فرمایا ہے۔ اور ابن مبارک نے بیان کیا کہ مجھ کو سفیان بن عیینہ نے خبر دی، کہا مجھ سے یزید بن خصیفہ نے بیان کیا، انہوں نے بسر بن سعید سے، کہا میں نے ابوسعید رضی اللہ عنہ سے سنا پھر یہی حدیث نقل کی۔"],"14196":["muslim",5641,"عمرو بن محمد بن بکیر ناقد نے کہا : ہمیں سفیان بن عینیہ نے حدیث بیان کی ، کہا : اللہ کی قسم!ہمیں یزید بن خصیفہ نے بسر بن سعید سے حدیث بیان کی ، کہا : میں نے سیدنا ابوسعید خدری رضی اللہ تعالی عنہ کو کہتے ہوئے سنا : میں مدینہ منورہ میں انصار کی مجلس میں بیٹھا ہوا تھا اتنے میں ابو موسی ڈرے سہمے ہوئے آئے ، ہم نے ان سے پوچھا آپ کو کیا ہوا؟ انھوں نے بتایا کہ سیدنا عمر رضی اللہ تعالی عنہ نے میری طرف پیغام بھیجا ہے کہ میں ان کے پاس آؤں ، میں ان کے دروازے پر گیا اور تین مرتبہ سلام کیا انھوں نے مجھے سلام کا جواب نہیں دیا تو میں لوٹ آیا ، انھوں نے کہا : آپ کو ہمارے پاس آنے سے کس بات نے روکا؟میں نے کہا : میں آیا تھا ، آپ کے دروازے پر کھڑے تین بار سلام کیا ، آپ لوگوں نے مجھے جواب نہیں دیا ، اس لئے میں لوٹ گیا کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا : \"\" جب تم میں سے کوئی شخص تین بار اجازت مانگے اور اسے اجازت نہ دی جائے تو وہ لوٹ جائے ۔ \"\" سیدنا عمر رضی اللہ تعالی عنہ نے فرمایا : اس پر گواہی پیش کرو ورنہ میں تم کو سزا دوں گا ۔ سیدنا ابی ابن کعب رضی اللہ تعالی عنہ نے کہا : ان کے ساتھ صرف وہ شخص جا کرکھڑا ہوگا جو قوم میں سے سب سے کم عمر ہے ، سیدنا ابو سعید رضی اللہ تعالی عنہ نے کہا : میں نے کہا کہ میں سب سے کم عمر ہوں توانھوں نے کہا : تم ان کے ساتھ جاؤ ( اور گواہی دو)"],"14197":["muslim",5649,"افضل بن موسی نے کہا : ہمیں طلحہ بن یحیی نے ابو بردہ سے خبر دی ، انھوں نے سیدنا ابو موسی اشعری رضی اللہ تعالی عنہ سے روایت کی ، کہا : ابو موسی اشعری رضی اللہ تعالی عنہ سیدنا عمر بن خطاب رضی اللہ تعالی عنہ کے پاس آئے اور کہا : السلام علیکم ، عبد اللہ بن قیس ( حاضر ہوا ) ہے ، انھوں نے آنے کی اجازت نہ دی ۔ انھوں نے پھر کہا : السلام علیکم ، یہ ابو موسی ہے ، السلام علیکم ، یہ اشعری ہے ، اس کے بعد چلے گئے ، سیدنا عمر رضی اللہ تعالی عنہ نے کہا : ان کو میرے پاس واپس لا ؤ ۔ میرے پاس واپس لا ؤ ۔ وہ آئے تو سیدنا عمر رضی اللہ تعالی عنہ نے کہا : ابو موسی !آپ کو کس بات نے لوٹا دیا ؟ ہم کا م میں مشغول تھے ۔ انھوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ نے فر ما یا : \"\" اجازت تین بار طلب کی جا ئے ، اگر تم کو اجازت دے دی جا ئے ( توآ جاؤ ) ورنہ لوٹ جا ؤ ۔ \"\" سیدنا عمر رضی اللہ تعالی عنہ نے کہا : یا تو آپ اس پر گواہ لا ئیں گے یا پھر میں یہ کروں گا تو سیدنا ابو موسی رضی اللہ تعالی عنہ چلے گئے ۔ سیدنا عمر رضی اللہ تعالی عنہ نے کہا ابو موسی کو گواہ مل گیا تو شام کو وہ تمھیں منبر کے پاس ملیں گے اور اگر ان کو گواہ نہیں ملا تو وہ تمھیں نہیں ملیں گے ، جب سیدنا عمر رضی اللہ تعالی عنہ شام کو آئے تو انھوں نے سیدنا ابو موسی رضی اللہ تعالی عنہ کو موجود پا یا ، انھوں نے کہا ابو موسی !کیا کہتے ہیں ؟آپ کو گواہ مل گیا ؟ انھوں نے کہا : ہاں! ابی بن کعب ہیں انھوں ( سیدنا عمر رضی اللہ تعالی عنہ ) نے کہا : وہ قابل اعتماد گواہ ہیں ۔ ( پھر ابو طفیل عامر بن واثلہ رضی اللہ تعالی عنہ کی طرف متوجہ ہو کر ) کہا : ابو طفیل !یہ ( ابی بن کعب رضی اللہ تعالی عنہ ) کیا کہتے ہیں ؟ انھوں ( سیدنا ابی بن کعب رضی اللہ تعالی عنہ ) نے کہا : ابن خطاب !میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ یہی فر ما رہے تھے ۔ لہٰذا آپ رسول اللہ صلی اللہ علیہ وسلم کے صحابہ کرام رضوان اللہ عنھم اجمعین پر عذاب نہ بنیں ۔ انھوں نے کہا : سبحان اللہ !میں نے ایک چیز سنی اور چاہا کہ اس کا ثبوت حاصل کروں ۔"],"14198":["bukhari",7353,"ہم سے مسدد بن مسرہد نے بیان کیا، کہا ہم سے یحیی بن سعید قطان نے بیان کیا، ان سے ابن جریج نے، ان سے عطاء بن ابی رباح نے، ان سے عبید بن عمیر نے بیان کیا کہ ابوموسیٰ اشعری رضی اللہ عنہ نے عمر رضی اللہ عنہ سے (ملنے کی) اجازت چاہی اور یہ دیکھ کر کہ عمر رضی اللہ عنہ مشغول ہیں آپ جلدی سے واپس چلے گئے۔ پھر عمر رضی اللہ عنہ نے کہا کہ کیا میں نے ابھی عبداللہ بن قیس(ابوموسیٰ رضی اللہ عنہ) کی آواز نہیں سنی تھی؟ انہیں بلا لو۔ چنانچہ انہیں بلایا گیا تو عمر رضی اللہ عنہ نے پوچھا کہ ایسا کیوں کیا؟ (جلدی واپس ہو گئے) انہوں نے کہا کہ ہمیں حدیث میں اس کا حکم دیا گیا ہے۔ عمر رضی اللہ عنہ نے کہا کہ اس حدیث پر کوئی گواہ لاؤ، ورنہ میں تمہارے ساتھ یہ (سختی) کروں گا۔ چنانچہ ابوموسیٰ رضی اللہ عنہ انصار کی ایک مجلس میں گئے انہوں نے کہا کہ اس کی گواہی ہم میں سب سے چھوٹا دے سکتا ہے۔ چنانچہ ابوسعید خدری رضی اللہ عنہ کھڑے ہوئے اور کہا کہ ہمیں دربار نبوی سے اس کا حکم دیا جاتا تھا۔ اس پر عمر رضی اللہ عنہ نے کہا کہ نبی کریم صلی اللہ علیہ وسلم کا یہ حکم مجھے معلوم نہیں تھا، مجھے بازار کے کاموں خرید و فروخت نے اس حدیث سے غافل رکھا۔"],"14200":["abudawud",5176,"کلدہ بن حنبل سے روایت ہے کہ صفوان بن امیہ رضی اللہ عنہ نے انہیں دودھ، ہرن کا بچہ اور چھوٹی چھوٹی ککڑیاں دے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس بھیجا، اس وقت آپ مکہ کے اونچائی والے حصہ میں تھے، میں آپ کے پاس گیا، اور آپ کو سلام نہیں کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: لوٹ کر (باہر) جاؤ اور (پھر سے آ کر) السلام علیکم کہو، یہ واقعہ صفوان بن امیہ کے اسلام قبول کر لینے کے بعد کا ہے۔"],"14201":["abudawud",5179,"بنو عامر کے ایک شخص سے روایت ہے کہ اس نے نبی اکرم صلی اللہ علیہ وسلم سے اجازت طلب کی، پھر راوی نے اسی مفہوم کی حدیث ذکر کی، اس میں ہے: \"میں نے اسے سن لیا تو میں نے کہا: \"السلام علیکم\" کیا میں اندر آ سکتا ہوں؟\"۔"],"14202":["abudawud",5201,"عمر رضی اللہ عنہ سے روایت ہے کہ وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے اور آپ اپنے ایک کمرے میں تھے، اور کہا: اللہ کے رسول! \"السلام عليكم\" کیا عمر اندر آ سکتا ہے؟ ۔"],"14203":["muslim",5684,"عبد الوحد بن زیاد نے کہا : ہمیں حسن بن عبید اللہ نے حدیث بیان کی ۔ کہا : ہمیں ابرا ہیم بن سوید نے حدیث سنائی کہا : میں نے عبد الرحمٰن بن یزید سے سنا ، انھوں نے کہا : میں نے سیدنا ابن مسعود رضی اللہ تعالی عنہ سے سنا ، کہہ رہے تھے رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فر ما یا : \" تمھا رے لیے میرے پاس آنے کی یہی اجازت ہے کہ حجاب اٹھا دیا جا ئے اور تم میرے راز کی بات سن لو ، ( یہ اجازت اس وقت تک ہے ) حتی کہ میں تمھیں روک دوں"],"14204":["bukhari",6246,"ہم سے ابونعیم نے بیان کیا، کہا ہم سے عمر بن ذر نے بیان کیا (دوسری سند) اور ہم سے محمد بن مقاتل نے بیان کیا، کہا ہم کو عبداللہ نے خبر دی، کہا ہم کو مجاہد نے خبر دی، اور ان سے ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ (آپ کے گھر میں) داخل ہوا نبی کریم صلی اللہ علیہ وسلم نے ایک بڑے پیالے میں دودھ پایا تو فرمایا ابوہریرہ! اہل صفہ کے پاس جا اور انہیں میرے پاس بلا لا۔ میں ان کے پاس آیا اور انہیں بلا لایا۔ وہ آئے اور (اندر آنے کی) اجازت چاہی پھر جب اجازت دی گئی تو داخل ہوئے۔"],"14205":["abudawud",5189,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"کسی آدمی کو بلا بھیجنا، ہی اس کی جانب سے اس کے لیے اجازت ہے\"۔"],"14206":["abudawud",5190,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب کوئی آدمی کھانے کے لیے بلایا جائے اور وہ بلانے والا آنے والے کے ساتھ ہی آ جائے تو یہ اس کے لیے اجازت ہے\" (پھر اسے اجازت لینے کی ضرورت نہیں) ۔ ابوعلی لؤلؤی کہتے ہیں: میں نے ابوداؤد کو کہتے سنا: کہ قتادہ نے ابورافع سے کچھ نہیں سنا ہے۔"],"14207":["abudawud",5186,"عبداللہ بن بسر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب کسی کے دروازے پر آتے تو دروازہ کے سامنے منہ کر کے نہ کھڑے ہوتے بلکہ دروازے کے چوکھٹ کے دائیں یا بائیں جانب کھڑے ہوتے، اور کہتے: \"السلام علیکم، السلام علیکم\" یہ ان دنوں کی بات ہے جب گھروں میں دروازوں پر پردے نہیں تھے۔"],"14208":["bukhari",6250,"ہم سے ابوالولید ہشام بن عبدالملک نے بیان کیا، کہا ہم سے شعبہ نے بیان کیا، ان سے محمد بن منکدر نے کہا کہ میں نے جابر رضی اللہ عنہ سے سنا، وہ بیان کرتے تھے کہ میں نبی کریم صلی اللہ علیہ وسلم کی خدمت میں اس قرض کے بارے میں حاضر ہوا جو میرے والد پر تھا۔ میں نے دروازہ کھٹکھٹایا۔ نبی کریم صلی اللہ علیہ وسلم نے دریافت فرمایا کہ کون ہیں؟ میں نے کہا میں نبی کریم صلی اللہ علیہ وسلم نے فرمایا میں، میں جیسے آپ نے اس جواب کو ناپسند فرمایا۔"],"14210":["bukhari",6227,"ہم سے یحیی بن جعفر نے بیان کیا، کہا ہم سے عبدالرزاق نے بیان کیا، ان سے معمر نے، ان سے ہمام نے اور ان سے ابوہریرہ رضی اللہ عنہ نے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا اللہ تعالیٰ نے آدم کو اپنی صورت پر بنایا، ان کی لمبائی ساٹھ ہاتھ تھی۔ جب انہیں پیدا کر چکا تو فرمایا کہ جاؤ اور ان فرشتوں کو جو بیٹھے ہوئے ہیں، سلام کرو اور سنو کہ تمہارے سلام کا کیا جواب دیتے ہیں، کیونکہ یہی تمہارا اور تمہاری اولاد کا سلام ہو گا۔ آدم علیہ السلام نے کہا: السلام علیکم! فرشتوں نے جواب دیا، السلام علیک ورحمۃ اللہ، انہوں نے آدم کے سلام پر ورحمۃ اللہ بڑھا دیا۔ پس جو شخص بھی جنت میں جائے گا آدم علیہ السلام کی صورت کے مطابق ہو کر جائے گا۔ اس کے بعد سے پھر خلقت کا قد و قامت کم ہوتا گیا، اب تک ایسا ہی ہوتا رہا۔ 2- بَابُ قَوْلِ اللَّهِ تَعَالَى: {يَا أَيُّهَا الَّذِينَ آمَنُوا لاَ تَدْخُلُوا بُيُوتًا غَيْرَ بُيُوتِكُمْ حَتَّى تَسْتَأْنِسُوا وَتُسَلِّمُوا عَلَى أَهْلِهَا ذَلِكُمْ خَيْرٌ لَكُمْ لَعَلَّكُمْ تَذَّكَّرُونَ فَإِنْ لَمْ تَجِدُوا فِيهَا أَحَدًا فَلاَ تَدْخُلُوهَا حَتَّى يُؤْذَنَ لَكُمْ وَإِنْ قِيلَ لَكُمُ ارْجِعُوا فَارْجِعُوا هُوَ أَزْكَى لَكُمْ وَاللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌ لَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَدْخُلُوا بُيُوتًا غَيْرَ مَسْكُونَةٍ فِيهَا مَتَاعٌ لَكُمْ وَاللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ}:"],"14211":["bukhari",6230,"ہم سے عمر بن حفص نے بیان کیا، انہوں نے کہا ہم سے ہمارے والد نے بیان کیا، انہوں نے کہا ہم سے اعمش نے بیان کیا، انہوں نے کہا کہ مجھ سے شقیق نے بیان کیا اور ان سے عبداللہ رضی اللہ عنہ نے بیان کیا کہ جب ہم (ابتداء اسلام میں) نبی کریم صلی اللہ علیہ وسلم کے ساتھ نماز پڑھتے تو کہتے سلام ہو اللہ پر اس کے بندوں سے پہلے، سلام ہو جبرائیل پر، سلام ہو میکائیل پر، سلام ہو فلاں پر، پھر(ایک مرتبہ) جب نبی کریم صلی اللہ علیہ وسلم نماز سے فارغ ہوئے تو ہماری طرف متوجہ ہو کر فرمایا کہ اللہ ہی سلام ہے۔ اس لیے جب تم میں سے کوئی نماز میں بیٹھے تو «التحيات لله، والصلوات والطيبات السلام عليك أيها النبي ورحمة الله وبركاته، السلام علينا وعلى عباد الله الصالحين.» الخ پڑھا کرے۔ کیونکہ جب وہ یہ دعا پڑھے گا تو آسمان و زمین کے ہر صالح بندے کو اس کی یہ دعا پہنچے گی۔ «أشهد أن لا إله إلا الله وأشهد أن محمدا عبده ورسوله.» اس کے بعد اسے اختیار ہے جو دعا چاہے پڑھے۔"],"14214":["bukhari",6235,"ہم سے قتیبہ نے بیان کیا، کہا ہم سے جریر نے بیان کیا، ان سے شیبانی نے، ان سے اشعث بن ابی الشعثاء نے، ان سے معاویہ بن سوید بن مقرن نے اور ان سے براء بن عازب رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں سات باتوں کا حکم دیا تھا۔ بیمار کی مزاج پرسی کرنے کا، جنازے کے پیچھے چلنے کا، چھینکنے والے کے جواب دینے کا۔ کمزور کی مدد کرنے کا، مظلوم کی مدد کرنے کا، افشاء سلام (سلام کا جواب دینے اور بکثرت سلام کرنے) کا، قسم (حق) کھانے والے کی قسم پوری کرنے کا، اور نبی کریم صلی اللہ علیہ وسلم نے چاندی کے برتن میں پینے سے منع فرمایا تھا اور سونے کی انگوٹھی پہننے سے ہمیں منع فرمایا تھا۔ میثر (ریشم کی زین) پر سوار ہونے سے، ریشم اور دیباج پہننے، قسی (ریشمی کپڑا) اور استبرق پہننے سے (منع فرمایا تھا)۔"],"14215":["muslim",112,"ابو معاویہ اور وکیع نے اعمش سے حدیث سنائی ، انہوں نے ابو صالح سے اور انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ’’ تم جنت میں داخل نہیں ہو گے یہاں تک کہ تم مومن ہو جاؤ ، اور تم مو من نہیں ہو سکتے یہاں تک کہ ایک دوسرے سے محبت کرو ۔ کیا تمہیں ایسی چیز نہ بتاؤں کہ جب تم اس پر عمل کرو تو ایک دوسرے کے ساتھ محبت کرنے لگو ، آپس میں سلام عام کرو ۔ ‘‘"],"14217":["ibnmajah",3693,"ابوامامہ رضی اللہ عنہ کہتے ہیں کہ ہمارے نبی کریم صلی اللہ علیہ وسلم نے ہمیں حکم دیا ہے کہ ہم سلام کو عام کریں اور پھیلائیں۔"],"14219":["tirmidhi",2485,"عبداللہ بن سلام رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب مدینہ تشریف لائے تو لوگ آپ کی طرف دوڑ پڑے، اور کہنے لگے: اللہ کے رسول آ گئے، اللہ کے رسول آ گئے، اللہ کے رسول آ گئے، چنانچہ میں بھی لوگوں کے ساتھ آیا تاکہ آپ کو دیکھوں، پھر جب میں نے آپ صلی اللہ علیہ وسلم کا چہرہ مبارک اچھی طرح دیکھا تو پہچان گیا کہ یہ کسی جھوٹے کا چہرہ نہیں ہو سکتا، اور سب سے پہلی بات جو آپ نے کہی وہ یہ تھی \"لوگو! سلام پھیلاؤ، کھانا کھلاؤ اور رات میں جب لوگ سو رہے ہوں تو نماز پڑھو، تم لوگ سلامتی کے ساتھ جنت میں داخل ہو گے\"۔"],"14220":["ibnmajah",3252,"عبداللہ بن عمر رضی اللہ عنہما کہتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سلام کو پھیلاؤ، کھانا کھلاؤ، اور بھائی بھائی ہو جاؤ جیسا کہ اللہ تعالی نے تمہیں حکم دیا ہے\"۔"],"14222":["abudawud",5197,"ابوامامہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کے نزدیک سب سے بہتر شخص وہ ہے جو سلام کرنے میں پہل کرے\"۔"],"14225":["bukhari",6236,"ہم سے عبداللہ بن یوسف نے بیان کیا، کہا ہم سے لیث بن سعد نے بیان کیا، کہا کہ مجھ سے یزید نے بیان کیا، ان سے ابوالخیر نے، ان سے عبداللہ بن عمر و رضی اللہ عنہ نے کہ ایک صاحب نے نبی کریم صلی اللہ علیہ وسلم سے پوچھا: اسلام کی کون سی حالت افضل ہے؟ نبی کریم صلی اللہ علیہ وسلم نے فرمایا یہ کہ (اللہ کی مخلوق کو) کھانا کھلاؤ اور سلام کرو، اسے بھی جسے تم پہچانتے ہو اور اسے بھی جسے نہیں پہچانتے۔"],"14226":["bukhari",6232,"ہم سے محمد نے بیان کیا، انہوں نے کہا ہم کو مخلد نے خبر دی، انہوں نے کہا ہم کو ابن جریج نے خبر دی، انہوں نے کہا کہ مجھے زیاد نے خبر دی، انہوں نے عبدالرحمٰن بن زید کے غلام ثابت سے سنا، اور انہوں نے ابوہریرہ رضی اللہ عنہ سے سنا۔ انہوں نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا سوار پیدل چلنے والے کو سلام کرے، پیدل چلنے والا بیٹھے ہوئے کو اور کم تعداد والے بڑی تعداد والوں کو۔"],"14227":["bukhari",6231,"ہم سے محمد بن مقاتل ابوالحسن نے بیان کیا، انہوں نے کہا ہم کو عبداللہ نے خبر دی، انہوں نے کہا ہم کو معمر نے خبر دی، انہیں ہمام بن منبہ نے اور انہیں ابوہریرہ رضی اللہ عنہ نے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا چھوٹا بڑے کو سلام کرے، گزرنے والا بیٹھنے والے کو سلام کرے اور چھوٹی جماعت بڑی جماعت کو پہلے سلام کرے۔"],"14228":["tirmidhi",2705,"فضالہ بن عبید رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سوار پیدل چلنے والے کو اور چلنے والا کھڑے ہوئے شخص کو اور تھوڑے لوگ زیادہ لوگوں کو سلام کریں\"۔"],"14231":["bukhari",6247,"ہم سے علی بن الجعد نے بیان کیا، انہوں نے کہا ہم کو شعبہ نے خبر دی، انہیں سیار نے انہوں نے ثابت بنانی سے روایت کی، انہیں انس بن مالک رضی اللہ عنہ نے کہ آپ بچوں کے پاس سے گزرے تو انہیں سلام کیا اور فرمایا کہ نبی کریم صلی اللہ علیہ وسلم بھی ایسا ہی کرتے تھے۔"],"14232":["muslim",6419,"ثابت نے سیدنا انس رضی اللہ تعالیٰ عنہ سے حدیث بیان کی کہا : رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لا ئے اس وقت میں لڑکوں کے ساتھ کھیل رہا تھا کہا : آپ نے ہم سب کو سلام کیا اور مجھے کسی کام کے لیے بھیج دیا تو میں اپنی والد ہ کے پاس تا خیر سے پہنچا ، جب میں آیا تو والدہ نے پو چھا : تمھیں دیر کیوں ہوئی ۔ ؟میں نے کہا : مجھے رسول اللہ صلی اللہ علیہ وسلم نے کسی کا م سے بھیجا تھا ۔ انھوں نے پو چھا : آپ کا وہ کام کیا تھا؟ میں نے کہا : وہ ایک راز ہے ۔ میری والدہ نے کہا : تم رسول اللہ صلی اللہ علیہ وسلم کا راز کسی پر افشانہ کرنا ۔ سیدنا انس رضی اللہ تعالیٰ عنہ نے کہا : اللہ کی قسم! ثابت !اگر میں وہ راز کسی کو بتاتا تو تمہیں ( جو رسول اللہ صلی اللہ علیہ وسلم کی حدیث کے طلبگار ہو ) ضرور بتا تا ۔"],"14233":["bukhari",6248,"ہم سے عبداللہ بن مسلمہ قعنبی نے بیان کیا، کہا ہم سے ابن ابی حازم نے ان سے ان کے والد نے اور ان سے سہل رضی اللہ عنہ نے کہ ہم جمعہ کے دن خوش ہوا کرتے تھے۔ میں نے عرض کی کس لیے؟ فرمایا کہ ہماری ایک بڑھیا تھیں جو مقام بضاعہ جایا کرتی تھیں۔ ابن سلمہ نے کہا کہ بضاعہ مدینہ منورہ کا کھجور کا ایک باغ تھا۔ پھر وہ وہاں سے چقندر لایا کرتی تھیں اور اسے ہانڈی میں ڈالتی تھیں اور جَو کے کچھ دانے پیس کر (اس میں ملاتی تھیں) جب ہم جمعہ کی نماز پڑھ کر واپس ہوتے تو انہیں سلام کرنے آتے اور وہ یہ چقندر کی جڑ میں آٹا ملی ہوئی دعوت ہمارے سامنے رکھتی تھیں ہم اس وجہ سے جمعہ کے دن خوش ہوا کرتے تھے اور قیلولہ یا دوپہر کا کھانا ہم جمعہ کے بعد کرتے تھے۔"],"14234":["abudawud",5204,"شہر بن حوشب کہتے ہیں کہ انہیں اسماء بنت یزید رضی اللہ عنہا نے خبر دی ہے کہ ہم عورتوں کے پاس سے نبی اکرم صلی اللہ علیہ وسلم گزرے تو آپ نے ہمیں سلام کیا۔"],"14235":["abudawud",5200,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ جب تم میں سے کوئی اپنے بھائی سے ملے تو اسے سلام کرے، پھر اگر ان دونوں کے درمیان درخت، دیوار یا پتھر حائل ہو جائے اور وہ اس سے ملے (ان کا آمنا سامنا ہو) تو وہ پھر اسے سلام کرے۔ معاویہ کہتے ہیں: مجھ سے عبدالوہاب بن بخت نے بیان کیا ہے انہوں نے ابوالزناد سے، ابوالزناد نے اعرج سے، اعرج نے ابوہریرہ سے اور ابوہریرہ نے رسول اللہ صلی اللہ علیہ وسلم سے ہو بہو اسی کے مثل روایت کیا ہے۔"],"14237":["abudawud",5208,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی مجلس میں پہنچے تو سلام کرے، اور پھر جب اٹھ کر جانے لگے تو بھی سلام کرے، کیونکہ پہلا دوسرے سے زیادہ حقدار نہیں ہے\" (بلکہ دونوں کی یکساں اہمیت و ضرورت ہے، جیسے مجلس میں شریک ہوتے وقت سلام کرے ایسے ہی مجلس سے رخصت ہوتے وقت بھی سب کو سلامتی کی دعا دیتا ہوا جائے) ۔"],"14238":["abudawud",5195,"عمران بن حصین رضی اللہ عنہما کہتے ہیں کہ ایک شخص نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا اور اس نے \"السلام علیکم\" کہا، آپ نے اسے سلام کا جواب دیا، پھر وہ بیٹھ گیا، تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اس کو دس نیکیاں ملیں\" پھر ایک اور شخص آیا، اس نے\"السلام علیکم ورحمتہ االله\" کہا، آپ نے اسے جواب دیا، پھر وہ شخص بھی بیٹھ گیا، آپ نے فرمایا: \"اس کو بیس نیکیاں ملیں\" پھر ایک اور شخص آیا اس نے \"السلام علیکم ورحمتہ االله وبرکاتہ\" کہا، آپ نے اسے بھی جواب دیا، پھر وہ بھی بیٹھ گیا، آپ نے فرمایا: \"اسے تیس نیکیاں ملیں\"۔"],"14240":["abudawud",4084,"ابوجری جابر بن سلیم رضی اللہ عنہ کہتے ہیں کہ میں نے ایک شخص کو دیکھا کہ لوگ اس کی رائے کو قبول کرتے ہیں جب بھی وہ کوئی بات کہتا ہے لوگ اسی کو تسلیم کرتے ہیں، میں نے پوچھا: یہ کون ہیں؟ لوگوں نے بتایا کہ یہ رسول اللہ صلی اللہ علیہ وسلم ہیں، میں نے دو مرتبہ کہا: «عليك السلام يا رسول الله» \"آپ پر سلام ہو اللہ کے رسول\" آپ صلی اللہ علیہ وسلم نے فرمایا: \" «عليك السلام»نہ کہو، یہ مردوں کا سلام ہے اس کے بجائے \" «السلام عليك» کہو۔\" میں اس اللہ کا بھیجا رسول ہوں، جس کو تمہیں کوئی ضرر لاحق ہو تو پکارو وہ تم سے اس ضرر کو دور فرما دے گا، جب تم پر کوئی قحط سالی آئے اور تم اسے پکارو تو وہ تمہارے لیے غلہ اگا دے گا، اور جب تم کسی چٹیل زمین میں ہو یا میدان پھر تمہاری اونٹنی گم ہو جائے تو اگر تم اس اللہ سے دعا کرو تو وہ اسے لے آئے گا\" میں نے کہا: مجھے نصیحت کیجئے آپ نے فرمایا: \"کسی کو بھی گالی نہ دو\"۔ اس کے بعد سے میں نے کسی کو گالی نہیں دی، نہ آزاد کو، نہ غلام کو، نہ اونٹ کو، نہ بکری کو، اور آپ صلی اللہ علیہ وسلم نے فرمایا: \"کسی بھی بھلائی کے کام کو معمولی نہ سمجھو، اور اگر تم اپنے بھائی سے خندہ پیشانی سے بات کرو گے تو یہ بھی بھلے کام میں داخل ہے، اور اپنا تہ بند نصف «ساق» (پنڈلی) تک اونچی رکھو، اور اگر اتنا نہ ہو سکے تو ٹخنوں تک رکھو، اور تہ بند کو ٹخنوں سے نیچے لٹکانے سے بچو کیونکہ یہ غرور و تکبر کی بات ہے، اور اللہ غرور پسند نہیں کرتا، اور اگر تمہیں کوئی گالی دے اور تمہارے اس عیب سے تمہیں عار دلائے جسے وہ جانتا ہے تو تم اسے اس کے اس عیب سے عار نہ دلاؤ جسے تم جانتے ہو کیونکہ اس کا وبال اسی پر ہو گا\"۔"],"14241":["bukhari",6251,"ہم سے اسحٰق بن منصور نے بیان کیا انہوں نے کہا ہم کو عبداللہ بن نمیر نے خبر دی، ان سے عبیداللہ نے بیان کیا، ان سے سعید بن ابی سعید مقبری نے بیان کیا اور ان سے ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ ایک شخص مسجد میں داخل ہوا، رسول اللہ صلی اللہ علیہ وسلم مسجد کے کنارے بیٹھے ہوئے تھے۔ اس نے نماز پڑھی اور پھر حاضر ہو کر نبی کریم صلی اللہ علیہ وسلم کو سلام کیا۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا وعلیک السلام واپس جا اور دوبارہ نماز پڑھ، کیونکہ تم نے نماز نہیں پڑھی۔ وہ واپس گئے اور نماز پڑھی۔ پھر (نبی کریم صلی اللہ علیہ وسلم ) کے پاس آئے اور سلام کیا آپ نے فرمایا وعلیک السلام۔ واپس جاؤ پھر نماز پڑھو۔ کیونکہ تم نے نماز نہیں پڑھی۔ وہ واپس گیا اور اس نے پھر نماز پڑھی۔ پھر واپس آیا اور نبی کریم صلی اللہ علیہ وسلم کی خدمت میں سلام عرض کیا۔ آپ صلی اللہ علیہ وسلم نے جواب میں فرمایا وعلیکم السلام۔ واپس جاؤ اور دوبارہ نماز پڑھو۔ کیونکہ تم نے نماز نہیں پڑھی۔ ان صاحب نے دوسری مرتبہ، یا اس کے بعد، عرض کیا: یا رسول اللہ! مجھے نماز پڑھنی سکھا دیجئیے۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ جب نماز کے لیے کھڑے ہوا کرو تو پہلے پوری طرح وضو کیا کرو، پھر قبلہ رو ہو کر تکبیر (تکبیر تحریمہ) کہو، اس کے بعد قرآن مجید میں سے جو تمہارے لیے آسان ہو وہ پڑھو، پھر رکوع کرو اور جب رکوع کی حالت میں برابر ہو جاؤ تو سر اٹھاؤ۔ جب سیدھے کھڑے ہو جاؤ تو پھر سجدہ میں جاؤ، جب سجدہ پوری طرح کر لو تو سر اٹھاؤ اور اچھی طرح سے بیٹھ جاؤ۔ یہی عمل اپنی ہر رکعت میں کرو۔ اور ابواسامہ راوی نے دوسرے سجدہ کے بعد یوں کہا کہ پھر سر اٹھا یہاں تک کہ سید ھا کھڑا ہو جا۔"],"14243":["bukhari",6249,"ہم سے ابن مقاتل نے بیان کیا، کہا ہم کو عبداللہ نے خبر دی، کہا ہم کو معمر نے خبر دی انہیں زہری نے انہیں ابوسلمہ بن عبدالرحمٰن نے اور ان سے عائشہ رضی اللہ عنہا نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا اے عائشہ! یہ جبرائیل ہیں تمہیں سلام کہتے ہیں بیان کیا کہ میں نے عرض کیا «وعليه السلام ورحمة الله» آپ دیکھتے ہیں جو ہم نہیں دیکھ سکتے ام المؤمنین کا اشارہ نبی کریم صلی اللہ علیہ وسلم کی طرف تھا۔ معمر کے ساتھ اس حدیث کو شعیب اور یونس اور نعمان نے بھی زہری سے روایت کیا ہے یونس اور نعمان کی روایتوں میں «وبركاته.» کا لفظ زیادہ ہے۔"],"14245":["muslim",5377,"شبانہ بن سوار نے کہا : ہمیں سلیمان بن مغیرہ نے ثابت سے حدیث بیان کی ، انھوں نے عبدالرحمان بن ابی لیلی سے ، انھوں نے سیدنا مقدار رضی اللہ تعالی عنہ سے روایت کی ، سیدنا مقداد رضی اللہ عنہ کہتے ہیں کہ میں اور میرے دونوں ساتھی آئے اور ( فاقہ وغیرہ کی ) تکلیف سے ہماری آنکھوں اور کانوں کی قوت جاتی رہی تھی ۔ ہم اپنے آپ کو رسول اللہ صلی اللہ علیہ وسلم کے اصحاب پر پیش کرتے تھے لیکن کوئی ہمیں قبول نہ کرتا تھا ۔ آخر ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تو آپ صلی اللہ علیہ وسلم ہمیں اپنے گھر لے گئے ۔ وہاں تین بکریاں تھیں ۔ آپ صلی اللہ علیہ وسلم نے فرمایا کہ ان کا دودھ دوہو ، ہم تم سب پئیں گے پھر ہم ان کا دودھ دوہا کرتے اور ہم میں سے ہر ایک اپنا حصہ پی لیتا اور رسول اللہ صلی اللہ علیہ وسلم کا حصہ رکھ چھوڑتے ۔ آپ صلی اللہ علیہ وسلم رات کو تشریف لاتے اور ایسی آواز سے سلام کرتے جس سے سونے والا نہ جاگے اور جاگنے والا سن لے ۔ پھر آپ صلی اللہ علیہ وسلم مسجد میں آتے ، نماز پڑھتے ، پھر اپنے دودھ کے پاس آتے اور اس کو پیتے ۔ ایک رات جب میں اپنا حصہ پی چکا تھا کہ شیطان نے مجھے بھڑکایا ۔ شیطان نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم تو انصار کے پاس جاتے ہیں ، وہ آپ صلی اللہ علیہ وسلم کو تحفے دیتے ہیں اور جو آپ صلی اللہ علیہ وسلم کو ضرورت ہے ، مل جاتا ہے آپ صلی اللہ علیہ وسلم کو اس ایک گھونٹ دودھ کی کیا ضرورت ہو گی؟ آخر میں آیا اور وہ دودھ پی گیا ۔ جب دودھ پیٹ میں سما گیا اور مجھے یقین ہو گیا کہ اب وہ دودھ نہیں ملنے کا تو اس وقت شیطان نے مجھے ندامت کی اور کہنے لگا کہ تیری خرابی ہو تو نے کیا کام کیا؟ تو نے رسول اللہ صلی اللہ علیہ وسلم کا حصہ پی لیا ، اب آپ صلی اللہ علیہ وسلم آئیں گے اور دودھ کو نہ پائیں گے تو تجھ پر بددعا کریں گے اور تیری دنیا اور آخرت دونوں تباہ ہوں گی ۔ میں ایک چادر اوڑھے ہوئے تھا جب اس کو پاؤں پر ڈالتا تو سر کھل جاتا اور جب سر ڈھانپتا تو پاؤں کھل جاتے تھے اور مجھے نیند بھی نہ آ رہی تھی جبکہ میرے ساتھی سو گئے اور انہوں نے یہ کام نہیں کیا تھا جو میں نے کیا تھا ۔ آخر رسول اللہ صلی اللہ علیہ وسلم آئے اور معمول کے موافق سلام کیا ، پھر مسجد میں آئے اور نماز پڑھی ، اس کے بعد دودھ کے پاس آئے ، برتن کھولا تو اس میں کچھ نہ تھا ۔ آپ صلی اللہ علیہ وسلم نے اپنا سر آسمان کی طرف اٹھایا میں سمجھا کہ اب آپ صلی اللہ علیہ وسلم بددعا کرتے ہیں اور میں تباہ ہوا ۔ آپ صلی اللہ علیہ وسلم نے فرمایا کہ اے اللہ! کھلا اس کو جو مجھے کھلائے اور پلا اس کو جو مجھے پلائے ۔ یہ سن کر میں نے اپنی چادر کو مضبوط باندھا ، چھری لی اور بکریوں کی طرف چلا کہ جو ان میں سے موٹی ہو اس کو رسول اللہ صلی اللہ علیہ وسلم کے لئے ذبح کروں ۔ دیکھا تو اس کے تھن میں دودھ بھرا ہوا ہے ۔ پھر دیکھا تو اور بکریوں کے تھنوں میں بھی دودھ بھرا ہوا ہے ۔ میں نے آپ صلی اللہ علیہ وسلم کے گھر والوں کا ایک برتن لیا جس میں وہ دودھ نہ دوہتے تھے ( یعنی اس میں دوہنے کی خواہش نہیں کرتے تھے ) ۔ اس میں میں نے دودھ دوہا ، یہاں تک کہ اوپر جھاگ آ گیا ( اتنا بہت دودھ نکلا ) اور میں اس کو لے کر آپ صلی اللہ علیہ وسلم کے پاس آیا تو آپ صلی اللہ علیہ وسلم نے فرمایا کہ تم نے اپنے حصے کا دودھ رات کو پیا یا نہیں؟ میں نے عرض کیا کہ یا رسول اللہ! آپ دودھ پیجئے ۔ آپ صلی اللہ علیہ وسلم نے پی کر مجھے دیا تو میں نے عرض کیا کہ یا رسول اللہ! اور پیجئے ۔ آپ صلی اللہ علیہ وسلم نے اور پیا ۔ پھر مجھے دیا ، جب مجھے معلوم ہو گیا کہ آپ صلی اللہ علیہ وسلم سیر ہو گئے اور آپ صلی اللہ علیہ وسلم کی دعا میں نے لے لی ہے ، تب میں ہنسا ، یہاں تک کہ خوشی کے مارے زمین پر گر گیا ۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ اے مقداد! تو نے کوئی بری بات کی؟ وہ کیا ہے؟ میں نے عرض کیا کہ یا رسول اللہ! میرا حال ایسا ہوا اور میں نے ایسا قصور کیا ۔ آپ صلی اللہ علیہ وسلم نے فرمایا کہ اس وقت کا دودھ ( جو خلاف معمول اترا ) اللہ کی رحمت تھی ۔ تو نے مجھ سے پہلے ہی کیوں نہ کہا ہم اپنے دونوں ساتھیوں کو بھی جگا دیتے کہ وہ بھی یہ دودھ پیتے؟ میں نے عرض کیا کہ قسم اس کی جس نے آپ صلی اللہ علیہ وسلم کو سچا کلام دے کر بھیجا ہے کہ اب مجھے کوئی پرواہ نہیں جب آپ نے اللہ کی رحمت حاصل کر لی اور میں نے آپ صلی اللہ علیہ وسلم کے ساتھ حاصل کی تو کوئی بھی اس کو حاصل کرے ۔"],"14246":["muslim",753,"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے ، ایک آدمی گزرا جبکہ رسول اللہ صلی اللہ علیہ وسلم پیشاب کر رہے تھے ، تو اس نے سلام کہا ، آپ صلی اللہ علیہ وسلم نے اسے سلام کا جواب نہ دیا ۔"],"14247":["muslim",5679,"عبد العزیز دراوردی نے سہیل سے ، انھوں نے اپنے والد سے ، انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالی عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرما یا : \" یہود نصاری ٰکو سلام کہنے میں ابتدانہ کرو اور جب تم ان میں سے کسی کو راستے میں ملو ( تو بجا ئے اس کے وہ یہ کام کرے ) تم اسے راستے کے تنگ حصے کی طرف جا نے پر مجبورکردو ۔"],"14248":["bukhari",6256,"ہم سے ابوالیمان نے بیان کیا، انہوں نے کہا ہم کو شعیب نے خبر دی، انہیں زہری نے، انہوں نے کہا کہ مجھے عروہ نے خبر دی، اور ان سے عائشہ رضی اللہ عنہا نے بیان کیا کہ کچھ یہودی رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور کہا کہ «السام عليك.»(تمہیں موت آئے) میں ان کی بات سمجھ گئی اور میں نے جواب دیا «عليكم السام واللعنة.» نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ عائشہ صبر سے کام لے کیونکہ اللہ تعالیٰ تمام معاملات میں نرمی کو پسند کرتا ہے، میں نے عرض کیا: یا رسول اللہ! کیا آپ نے نہیں سنا کہ انہوں نے کیا کہا تھا؟ نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ میں نے ان کو جواب دے دیا تھا کہ «وعليكم» (اور تمہیں بھی)۔"],"14249":["malik",3,"روایت ہے عطا بن یسار سے ایک شخص آیا رسول اللہ صلی اللہ علیہ وسلم کے پاس اور پوچھا آپ صلی اللہ علیہ وسلم سے نماز صبح کا وقت تو چپ ہو رہے آپ صلی اللہ علیہ وسلم جب دوسرا روز ہوا نماز پڑھی آپ صلی اللہ علیہ وسلم نے اندھیرے منہ صبح صادق نکلتے ہی پھر تیسرے روز نماز پڑھی فجر کی روشنی میں اور فرمایا کہ کہاں ہے وہ شخص جس نے نماز فجر کا وقت دریافت کیا تھا اور وہ شخص بول اٹھا میں ہوں یا رسول اللہ صلی اللہ علیہ وسلم فرمایا آپ صلی اللہ علیہ وسلم نے نماز فجر کا وقت ان دونوں کے بیچ ہے ۔"],"14250":["muslim",5678,"ابوزبیر نے کہا : انھوں نے سیدنا جابر بن عبد اللہ رضی اللہ تعالی عنہ کو کہتے ہوئے سنا : یہود میں سے کچھ لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کو سلام کیا اور کہا ( السام عليك يا أبا القاسم ) ( ابو القاسم ) آپ پر مو ت ہو!اس پر آپ نے فر ما یا : \" تم پرہو ۔ \" سیدہ عائشہ رضی اللہ تعالی عنہا کہنے لگیں اور وہ غصے میں آگئی تھیں ۔ کیا آپ نے نہیں سنا ، جو انھوں نے کہا ہے ؟ آپ نے فر ما یا : \" کیوں نہیں !میں نے سنا ہے اور میں نے ان کو جواب دے دیا ہے اور ان کے خلاف ہماری دعا قبول ہو تی ہے اور ہمارے خلا ف ان کی دعا قبول نہیں ہو تی ۔"],"14252":["bukhari",6258,"ہم سے عثمان بن ابی شیبہ نے بیان کیا، انہوں نے کہا ہم سے ہشیم نے بیان کیا، انہیں عبداللہ بن ابی بکر بن انس نے خبر دی، ان سے انس بن مالک رضی اللہ عنہ نے بیان کیا کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا جب اہل کتاب تمہیں سلام کریں تو تم اس کے جواب میں صرف «وعليكم» کہو۔"],"14253":["bukhari",6926,"ہم سے محمد بن مقاتل ابوالحسن مروزی نے بیان کیا، کہا ہم کو عبداللہ بن مبارک نے خبر دی، کہا ہم کو شعبہ بن حجاج نے، انہوں نے ہشام بن زید بن انس سے، وہ کہتے تھے میں نے اپنے دادا انس بن مالک رضی اللہ عنہ سے سنا، وہ کہتے تھے کہ ایک یہودی نبی کریم صلی اللہ علیہ وسلم کے پاس سے گزرا کہنے لگا «السام عليك.» یعنی تم مرو۔ نبی کریم صلی اللہ علیہ وسلم نے جواب میں صرف «وعليك\".» کہا(تو بھی مرے گا) پھر آپ صلی اللہ علیہ وسلم نے صحابہ رضی اللہ عنہم سے فرمایا کہ تم کو معلوم ہوا، اس نے کیا کہا؟ اس نے «السام عليك.» کہا۔ صحابہ نے عرض کیا: یا رسول اللہ! (حکم ہو تو) اس کو مار ڈالیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا، نہیں۔ جب کتاب والے یہود اور نصاریٰ تم کو سلام کیا کریں تو تم بھی یہی کہا کرو «وعليكم» ۔"],"14254":["muslim",5674,"سفیان بن عیینہ نے ہمیں زہری سے حدیث بیان کی انھوں نے عروہ سے ، انھوں نے سیدہ عائشہ رضی اللہ تعالی عنہا سے روایت کی ، کہا : یہودیوں کی ایک جماعت نے رسول اللہ صلی اللہ علیہ وسلم سے ملنے کے لیے اجازت طلب کی اور انھوں نے کہا ( «اَلسَامُ عَلَيكُم» ) ( آپ پر مو ت ہو! ) سیدہ عائشہ رضی اللہ تعالی عنہا نے کہا : بلکہ تم پر موت ہو اور لعنت ہو ۔ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : عائشہ !اللہ تعا لی ہر معا ملے میں نرمی پسند فر ما تا ہے ۔ سیدہ عائشہ رضی اللہ تعالی عنہا نے عرض کی : کیا آپ نے سنا نہیں کہ انھوں نے کیا کہا تھا ؟آپ صلی اللہ علیہ وسلم نے فر ما یا : میں نے ( «وَ عَلَيكُم» ) ( اور تم پرہو ) کہہ دیاتھا ۔"],"14255":["bukhari",6254,"ہم سے ابراہیم بن موسیٰ نے بیان کیا، کہا ہم کو ہشام بن عروہ نے خبر دی، انہیں معمر نے، انہیں زہری نے، ان سے عروہ بن زبیر نے بیان کیا کہ مجھے اسامہ بن زید رضی اللہ عنہما نے خبر دی کہ نبی کریم صلی اللہ علیہ وسلم ایک گدھے پر سوار ہوئے جس پر پالان بندھا ہوا تھا اور نیچے فدک کی بنی ہوئی ایک مخملی چادر بچھی ہوئی تھی۔ نبی کریم صلی اللہ علیہ وسلم نے سواری پر اپنے پیچھے اسامہ بن زید رضی اللہ عنہما کو بٹھایا تھا۔ آپ بنی حارث بن خزرج میں سعد بن عبادہ رضی اللہ عنہ کی عیادت کے لیے تشریف لے جا رہے تھے۔ یہ جنگ بدر سے پہلے کا واقعہ ہے۔ نبی کریم صلی اللہ علیہ وسلم ایک مجلس پر سے گزرے جس میں مسلمان، بت پرست، مشرک اور یہودی سب ہی شریک تھے۔ عبداللہ بن ابی ابن سلول بھی ان میں تھا۔ مجلس میں عبداللہ بن رواحہ بھی موجود تھے۔ جب مجلس پر سواری کا گرد پڑا تو عبداللہ نے اپنی چادر سے اپنی ناک چھپا لی اور کہا کہ ہمارے اوپر غبار نہ اڑاؤ۔ پھر نبی کریم صلی اللہ علیہ وسلم نے سلام کیا اور وہاں رک گئے اور اتر کر انہیں اللہ کی طرف بلایا اور ان کے لیے قرآن مجید کی تلاوت کی۔ عبداللہ بن ابی ابن سلول بولا، میاں میں ان باتوں کے سمجھنے سے قاصر ہوں اگر وہ چیز حق ہے جو تم کہتے ہو تو ہماری مجلسوں میں آ کر ہمیں تکلیف نہ دیا کرو۔ اس پر ابن رواحہ نے کہا یا رسول اللہ! آپ ہماری مجلسوں میں تشریف لایا کریں کیونکہ ہم اسے پسند کرتے ہیں۔ پھر مسلمانوں، مشرکوں اور یہودیوں میں اس بات پر تو تو میں میں ہونے لگی اور قریب تھا کہ وہ کوئی ارادہ کر بیٹھیں اور ایک دوسرے پر حملہ کر دیں۔ لیکن نبی کریم صلی اللہ علیہ وسلم انہیں برابر خاموش کراتے رہے اور جب وہ خاموش ہو گئے تو نبی کریم صلی اللہ علیہ وسلم اپنی سواری پر بیٹھ کر سعد بن عبادہ رضی اللہ عنہ کے یہاں گئے۔ نبی کریم صلی اللہ علیہ وسلم نے ان سے فرمایا، سعد تم نے نہیں سنا کہ ابوحباب نے آج کیا بات کہی ہے۔ آپ کا اشارہ عبداللہ بن ابی کی طرف تھا کہ اس نے یہ یہ باتیں کہی ہیں۔ سعد نے عرض کیا کہ یا رسول اللہ! اسے معاف کر دیجئیے اور درگزر فرمائیے۔ اللہ تعالیٰ نے وہ حق آپ کو عطا فرمایا ہے جو عطا فرمانا تھا۔ اس بستی (مدینہ منورہ) کے لوگ (آپ کی تشریف آوری سے پہلے) اس پر متفق ہو گئے تھے کہ اسے تاج پہنا دیں اور شاہی عمامہ اس کے سر پر باندھ دیں لیکن جب اللہ تعالیٰ نے اس منصوبہ کو اس حق کی وجہ سے ختم کر دیا جو اس نے آپ کو عطا فرمایا ہے تو اسے حق سے حسد ہو گیا اور اسی وجہ سے اس نے یہ معاملہ کیا ہے جو آپ نے دیکھا۔ چنانچہ نبی کریم صلی اللہ علیہ وسلم نے اسے معاف کر دیا۔ 21- بَابُ مَنْ لَمْ يُسَلِّمْ عَلَى مَنِ اقْتَرَفَ ذَنْبًا، وَلَمْ يَرُدَّ سَلاَمَهُ حَتَّى تَتَبَيَّنَ تَوْبَتُهُ، وَإِلَى مَتَى تَتَبَيَّنُ تَوْبَةُ الْعَاصِي:"],"14256":["bukhari",6263,"ہم سے عمرو بن عاصم نے بیان کیا، کہا ہم سے ہمام نے بیان کیا ان سے قتادہ نے کہ میں نے انس رضی اللہ عنہ سے پوچھا، کیا مصافحہ کا دستور نبی کریم صلی اللہ علیہ وسلم کے صحابہ میں تھا؟ انہوں نے کہا کہ جی ہاں ضرور تھا۔"],"14257":["abudawud",5213,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ جب یمن کے لوگ آئے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تمہارے پاس یمن کے لوگ آئے ہیں یہ وہ لوگ ہیں جنہوں نے سب سے پہلے مصافحہ کرنا شروع کیا\"۔"],"14259":["abudawud",5212,"براء رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب دو مسلمان آپس میں ملتے اور دونوں ایک دوسرے سے مصافحہ کرتے ہیں تو ان دونوں کے ایک دوسرے سے علیحدہ ہونے سے پہلے ہی ان کی مغفرت ہو جاتی ہے\"۔"],"14260":["tirmidhi",1597,"امیمہ بنت رقیقہ رضی اللہ عنہا کہتی ہیں کہ میں نے کئی عورتوں کے ساتھ رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی، آپ نے ہم سے فرمایا: \"اطاعت اس میں لازم ہے جو تم سے ہو سکے اور جس کی تمہیں طاقت ہو\"، میں نے کہا: اللہ اور اس کے رسول ہم پر خود ہم سے زیادہ مہربان ہیں، میں نے عرض کیا: اللہ کے رسول! ہم سے بیعت لیجئے (سفیان بن عیینہ کہتے ہیں: ان کا مطلب تھا مصافحہ کیجئے)، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم سو عورتوں کے لیے میرا قول میرے اس قول جیسا ہے جو ایک عورت کے لیے ہے\"۔"],"14262":["bukhari",6264,"ہم سے یحیی بن سلیمان نے بیان کیا، انہوں نے کہا کہ مجھ سے ابن وہب نے بیان کیا، انہوں نے کہا کہ مجھے حیوہ نے خبر دی، کہا کہ مجھ سے ابوعقیل زہرہ بن معبد نے بیان کیا، انہوں نے اپنے دادا عبداللہ بن ہشام رضی اللہ عنہ سے سنا، انہوں نے بیان کیا کہ ہم نبی کریم صلی اللہ علیہ وسلم کے ساتھ تھے اور نبی کریم صلی اللہ علیہ وسلم عمر بن خطاب رضی اللہ عنہ کا ہاتھ پکڑے ہوئے تھے۔"],"14266":["bukhari",6265,"ہم سے ابونعیم نے بیان کیا، کہا ہم سے سیف نے بیان کیا، انہوں نے کہا کہ میں نے مجاہد سے سنا، انہوں نے کہا کہ مجھ سے عبداللہ بن بخرہ ابومعمر نے بیان کیا کہ میں نے عبداللہ بن مسعود رضی اللہ عنہ سے سنا، انہوں نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے تشہد سکھایا، اس وقت میرا ہاتھ نبی کریم صلی اللہ علیہ وسلم کی ہتھیلیوں کے درمیان میں تھا (اس طرح سکھایا) جس طرح آپ قرآن کی سورت سکھایا کرتے تھے۔ «التحيات لله والصلوات والطيبات، السلام عليك أيها النبي ورحمة الله وبركاته، السلام علينا وعلى عباد الله الصالحين، أشهد أن لا إله إلا الله وأشهد أن محمدا عبده ورسوله.» نبی کریم صلی اللہ علیہ وسلم اس وقت حیات تھے۔ جب آپ کی وفات ہو گئی تو ہم (خطاب کا صیغہ کے بجائے) اس طرح پڑھنے لگے «السلام. على النبي» یعنی نبی کریم صلی اللہ علیہ وسلم پر سلام ہو۔"],"14267":["abudawud",2600,"قزعہ کہتے ہیں کہ مجھ سے ابن عمر رضی اللہ عنہما نے کہا: آؤ میں تمہیں اسی طرح رخصت کروں جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے رخصت کیا تھا: «أستودع الله دينك وأمانتك وخواتيم عملك» \"میں تمہارے دین، تمہاری امانت اور تمہارے انجام کار کو اللہ کے سپرد کرتا ہوں\"۔"],"14269":["abudawud",4794,"انس رضی اللہ عنہ کہتے ہیں کہ میں نے کسی شخص کو نہیں دیکھا جس نے رسول اللہ صلی اللہ علیہ وسلم کے کان پر منہ رکھا ہو (کچھ کہنے کے لیے) تو آپ نے اپنا سر ہٹا لیا ہو یہاں تک کہ خود وہی شخص نہ ہٹا لے، اور میں نے ایسا بھی کوئی شخص نہیں دیکھا، جس نے آپ کا ہاتھ پکڑا ہو، تو آپ نے اس سے ہاتھ چھڑا لیا ہو، یہاں تک کہ خود اس شخص نے آپ کا ہاتھ نہ چھوڑ دیا ہو۔"],"14270":["bukhari",3918,"براء نے بیان کیا کہ جب میں ابوبکر رضی اللہ عنہ کے ساتھ ان کے گھر میں داخل ہوا تھا تو آپ کی صاحبزادی عائشہ رضی اللہ عنہا لیٹی ہوئی تھیں انہیں بخار آ رہا تھا میں نے ان کے والد کو دیکھا کہ انہوں نے ان کے رخسار پر بوسہ دیا اور دریافت کیا بیٹی! طبیعت کیسی ہے؟"],"14271":["bukhari",5997,"ہم سے ابوالیمان نے بیان کیا، انہوں نے کہا ہم کو شعیب نے خبر دی، انہیں زہری نے خبر دی، ان سے ابوسلمہ بن عبدالرحمٰن نے بیان کیا اور ان سے ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے حسن بن علی رضی اللہ عنہ کو بوسہ دیا۔ نبی کریم صلی اللہ علیہ وسلم کے پاس اقرع بن حابس رضی اللہ عنہ بیٹھے ہوئے تھے۔ اقرع رضی اللہ عنہ نے اس پر کہا کہ میرے دس لڑکے ہیں اور میں نے ان میں سے کسی کو بوسہ نہیں دیا۔ نبی کریم صلی اللہ علیہ وسلم نے ان کی طرف دیکھا اور فرمایا کہ جو اللہ کی مخلوق پر رحم نہیں کرتا اس پر بھی رحم نہیں کیا جاتا۔"],"14272":["bukhari",5998,"ہم سے محمد بن یوسف نے بیان کیا، کہا ہم سے سفیان نے بیان کیا، ان سے ہشام نے، ان سے عروہ نے اور ان سے عائشہ رضی اللہ عنہا نے بیان کیا کہ ایک دیہاتی نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور کہا آپ لوگ بچوں کو بوسہ دیتے ہیں، ہم تو انہیں بوسہ نہیں دیتے۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ اگر اللہ نے تمہارے دل سے رحم نکال دیا ہے تو میں کیا کر سکتا ہوں۔"],"14273":["abudawud",5219,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"عائشہ! خوش ہو جاؤ اللہ نے کلام پاک میں تیرے عذر سے متعلق آیت نازل فرما دی ہے\" اور پھر آپ نے قرآن پاک کی وہ آیتیں انہیں پڑھ کر سنائیں، تو اس وقت میرے والدین نے کہا: اٹھو اور رسول اللہ صلی اللہ علیہ وسلم کے سر مبارک کو چوم لو، میں نے کہا: میں تو اللہ عزوجل کا شکر ادا کرتی ہوں (کہ اس نے میری پاکدامنی کے متعلق آیتیں اتاریں) نہ کہ آپ دونوں کا (کیونکہ آپ دونوں کو بھی تو مجھ پر شبہ ہونے لگا تھا) ۔"],"14274":["tirmidhi",3872,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے اٹھنے بیٹھنے کے طور و طریق اور عادت و خصلت میں فاطمہرضی اللہ عنہ سے زیادہ رسول اللہ صلی اللہ علیہ وسلم کے مشابہ کسی کو نہیں دیکھا، وہ کہتی ہیں: جب وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس آتیں تو آپ اٹھ کر انہیں بوسہ لیتے اور انہیں اپنی جگہ پر بٹھاتے، اور جب نبی اکرم صلی اللہ علیہ وسلم ان کے پاس آتے تو وہ اٹھ کر آپ کو بوسہ لیتیں اور آپ کو اپنی جگہ پر بٹھاتیں چنانچہ جب نبی اکرم صلی اللہ علیہ وسلم بیمار ہوئے تو فاطمہ آئیں اور آپ پر جھکیں اور آپ کو بوسہ لیا، پھر اپنا سر اٹھایا اور رونے لگیں پھر آپ پر جھکیں اور اپنا سر اٹھایا تو ہنسنے لگیں، پہلے تو میں یہ خیال کرتی تھی کہ یہ ہم عورتوں میں سب سے زیادہ عقل والی ہیں مگر ان کے ہنسنے پر یہ سمجھی کہ یہ بھی آخر (عام) عورت ہی ہیں، یعنی یہ کون سا موقع ہنسنے کا ہے، پھر جب نبی اکرم صلی اللہ علیہ وسلم کی وفات ہو گئی تو میں نے ان سے پوچھا کہ یہ کیا بات تھی کہ میں نے تمہیں دیکھا کہ تم نبی اکرم صلی اللہ علیہ وسلم پر جھکیں پھر سر اٹھایا تو رونے لگیں، پھر جھکیں اور سر اٹھایا تو ہنسنے لگیں، تو انہوں نے کہا: اگر آپ کی زندگی میں یہ بات بتا دیتی تو میں ایک ایسی عورت ہوتی جو آپ کے راز کو افشاء کرنے والی ہوتی، بات یہ تھی کہ پہلے آپ نے مجھے اس بات کی خبر دی کہ اس بیماری میں میں انتقال کر جانے والا ہوں، یہ سن کر میں رو پڑی، پھر آپ نے مجھے بتایا کہ ان کے گھر والوں میں سب سے پہلے میں ان سے ملوں گی، تو یہ سن کر میں ہنسنے لگی۔"],"14279":["bukhari",1343,"ہم سے عبداللہ بن یوسف نے بیان کیا ‘ انہوں نے کہا کہ ہم سے لیث بن سعد نے بیان کیا ‘ انہوں نے کہا کہ مجھ سے ابن شہاب نے بیان کیا ‘ ان سے عبدالرحمٰن بن کعب بن مالک نے ‘ ان سے جابر بن عبداللہ رضی اللہ عنہما نے کہ نبی کریم صلی اللہ علیہ وسلم نے احد کے دو دو شہیدوں کو ملا کر ایک ہی کپڑے کا کفن دیا۔ آپ صلی اللہ علیہ وسلم دریافت فرماتے کہ ان میں قرآن کسے زیادہ یاد ہے۔ کسی ایک کی طرف اشارہ سے بتایا جاتا تو آپ صلی اللہ علیہ وسلم بغلی قبر میں اسی کو آگے کرتے اور فرماتے کہ میں قیامت میں ان کے حق میں شہادت دوں گا۔ پھر آپ صلی اللہ علیہ وسلم نے سب کو ان کے خون سمیت دفن کرنے کا حکم دیا۔ نہ انہیں غسل دیا گیا اور نہ ان کی نماز جنازہ پڑھی گئی۔"],"14280":["abudawud",4843,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"معمر اور سن رسیدہ مسلمان کی اور حافظ قرآن کی جو نہ اس میں غلو کرنے والا ہواور نہ اس سے دور پڑ جانے والا ہو، اور عادل بادشاہ کی عزت و تکریم دراصل اللہ کے اجلال و تکریم ہی کا ایک حصہ ہے۔"],"14281":["bukhari",6176,"ہم سے عمران بن میسرہ نے بیان کیا، کہا ہم سے عبدالوارث نے بیان کیا، ان سے ابوالتیاح یزید بن حمید نے بیان کیا، ان سے ابوحمزہ نے اور ان سے ابن عباس رضی اللہ عنہما نے بیان کیا کہ جب قبیلہ عبدالقیس کا وفد نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ مرحبا ان لوگوں کو جو آن پہنچے تو نہ وہ ذلیل ہوئے، نہ شرمندہ (خوشی سے مسلمان ہو گئے ورنہ مارے جاتے شرمندہ ہوتے) انہوں نے عرض کیا: یا رسول اللہ! ہم قبیلہ ربیع کی شاخ سے تعلق رکھتے ہیں اور چونکہ ہمارے اور آپ کے درمیان قبیلہ مضر کے کافر لوگ حائل ہیں اس لیے ہم آپ کی خدمت میں صرف حرمت والے مہینوں ہی میں حاضر ہو سکتے ہیں (جن میں لوٹ کھسوٹ نہیں ہوتی) آپ کچھ ایسی جچی تلی بات بتا دیں جس پر عمل کرنے سے ہم جنت میں داخل ہو جائیں اور جو لوگ نہیں آ سکے ہیں انہیں بھی اس کی دعوت پہنچائیں۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ چار چار چیزیں ہیں۔ نماز قائم کرو، زکوٰۃ دو، رمضان کے روزے رکھو اور غنیمت کا پانچواں حصہ (بیت المال کو) ادا کرو اور دباء، حنتم، نقیر اور مزفت میں نہ پیو۔"],"14282":["bukhari",357,"ہم سے اسماعیل بن ابی اویس نے بیان کیا، کہا مجھ سے امام مالک بن انس نے عمر بن عبیداللہ کے غلام ابونضر سالم بن امیہ سے کہ ام ہانی بنت ابی طالب کے غلام ابومرہ یزید نے بیان کیا کہ انہوں نے ام ہانی بنت ابی طالب سے یہ سنا۔ وہ فرماتی تھیں کہ میں فتح مکہ کے موقع پر نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی۔ میں نے دیکھا کہ آپ غسل کر رہے ہیں اور آپ کی صاحبزادی فاطمہ رضی اللہ عنہا پردہ کئے ہوئے ہیں۔ انہوں نے کہا کہ میں نے نبی کریم صلی اللہ علیہ وسلم کو سلام کیا۔ آپ صلی اللہ علیہ وسلم نے پوچھا کہ کون ہے؟ میں نے بتایا کہ ام ہانی بنت ابی طالب ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا اچھی آئی ہو، ام ہانی۔ پھر جب آپ صلی اللہ علیہ وسلم نہانے سے فارغ ہو گئے تو اٹھے اور آٹھ رکعت نماز پڑھی، ایک ہی کپڑے میں لپٹ کر۔ جب آپ صلی اللہ علیہ وسلم نماز پڑھ چکے تو میں نے عرض کی کہ یا رسول اللہ! میری ماں کے بیٹے (علی بن ابی طالب) کا دعویٰ ہے کہ وہ ایک شخص کو ضرور قتل کرے گا۔ حالانکہ میں نے اسے پناہ دے رکھی ہے۔ یہ (میرے خاوند) ہبیرہ کا فلاں بیٹا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ ام ہانی جسے تم نے پناہ دے دی، ہم نے بھی اسے پناہ دی۔ ام ہانی نے کہا کہ یہ نماز چاشت تھی۔"],"14283":["abudawud",4820,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"مجالس میں بہتر وہ ہے جو زیادہ کشادہ ہو\"۔"],"14284":["malik",4,"ام المومنین عائشہ رضی اللہ تعالی عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم پڑھتے تھے فجر کی نماز پھر عورتیں نماز سے فارغ ہو کر پلٹتی تھیں چادریں لپیٹی ہوئیں اور پہچانی نہ جاتی تھیں اندھیرے سے ۔"],"14285":["abudawud",4825,"جابر بن سمرہ رضی اللہ عنہ کہتے ہیں کہ جب ہم نبی اکرم صلی اللہ علیہ وسلم کے پاس آتے، تو ہم میں سے جس کو جہاں جگہ ملتی بیٹھ جاتا۔"],"14286":["bukhari",6270,"ہم سے خلاد بن یحیی نے بیان کیا، کہا ہم سے سفیان ثوری نے بیان کیا، ان سے عبداللہ عمری نے، ان سے نافع اور ان سے عبداللہ بن عمر رضی اللہ عنہما نے کہ نبی کریم صلی اللہ علیہ وسلم نے اس سے منع فرمایا تھا کہ کسی شخص کو اس کی جگہ سے اٹھایا جائے تاکہ دوسرا اس کی جگہ پر بیٹھے، البتہ (آنے والے کو مجلس میں) جگہ دے دیا کرو اور فراخی کر دیا کرو اور ابن عمر رضی اللہ عنہما ناپسند کرتے تھے کہ کوئی شخص مجلس میں سے کسی کو اٹھا کر خود اس کی جگہ بیٹھ جائے۔ 33- بَابُ مَنْ قَامَ مِنْ مَجْلِسِهِ أَوْ بَيْتِهِ، وَلَمْ يَسْتَأْذِنْ أَصْحَابَهُ، أَوْ تَهَيَّأَ لِلْقِيَامِ لِيَقُومَ النَّاسُ:"],"14287":["muslim",5707,"ابو زبیر نے سیدنا جا بر رضی اللہ تعالی عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فر ما یا : \" تم میں سے کو ئی شخص جمعے کے دن اپنے بھا ئی کو کھڑا نہ کرے کہ پھر دوسری طرف سے آکر اس کی جگہ پر خود بیٹھ جائے ، بلکہ ( جو آئے وہ ) کہے \" جگہ کشادہ کردو ۔"],"14289":["abudawud",4845,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کسی شخص کے لیے یہ جائز نہیں کہ وہ دو آدمیوں کے درمیان ان کی اجازت کے بغیر گھس کر دونوں میں جدائی ڈال دے\"۔"],"14291":["muslim",5708,"ابو عوانہ اور عبد العزیز بن محمد دونوں نے سہیل سے ، انھوں نے اپنے والد سے ، انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالی عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" جب تم میں سے کو ئی شخص کھڑا ہو \" اور ابوعوانہ کی حدیث میں ہے \" جب تم میں سے کو ئی شخص اپنی جگہ سے کھڑا ہو ۔ پھر اس جگہ لوٹ آئے تو وہی اس ( جگہ ) کا زیادہ حقدار ہے ۔ ۔"],"14292":["tirmidhi",2751,"وہب بن حذیفہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"آدمی اپنے بیٹھنے کی جگہ کا زیادہ مستحق ہے، اگر وہ کسی ضرورت سے اٹھ کر جائے اور پھر واپس آئے تو وہی اپنی جگہ پر بیٹھنے کا زیادہ حق رکھتا ہے\"۔"],"14293":["muslim",1967,"سیدنا ابو رفاعہ ( تمیم بن اُسید عدوی رضی اللہ تعالیٰ عنہ ) نے کہا کہ میں نبی صلی اللہ علیہ وسلم کے پاس ( اس وقت ) پہنچا جبکہ آپ خطبہ دے رہے تھے ، میں نے عرض کی : اے اللہ کے رسول صلی اللہ علیہ وسلم !ایک پردیسی آدمی ہے اپنے دین کے بارے میں پوچھنے آیا ہے اسے معلوم نہیں کہ ا س کادین کیا ہے کہا : تو رسول اللہ صلی اللہ علیہ وسلم میری طرف متوجہ ہوئے اور اپنا خطبہ چھوڑا ، یہاں تک کہ میرے پاس پہنچ گئے ۔ ایک کرسی لائی گئی میرے خیال میں اس کے پائے لوہے کے تھے ، کہا : تو رسول اللہ صلی اللہ علیہ وسلم اس پر بیٹھ گئے اور اللہ تعالیٰ نے جو کچھ آپ کو سکھایا تھا اس میں سے مجھے سکھانے لگے پھر اپنے خطبے کے لئے بڑھے اور اس کا آخری حصہ مکمل فرمایا ۔"],"14294":["ibnmajah",3722,"بریدہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے دھوپ اور سایہ کے درمیان میں بیٹھنے سے منع کیا ہے۔"],"14296":["abudawud",4848,"شرید بن سوید رضی اللہ عنہ کہتے ہیں کہ میرے پاس سے رسول اللہ صلی اللہ علیہ وسلم گزرے اور میں اس طرح بیٹھا ہوا تھا کہ میں نے اپنا بایاں ہاتھ اپنی پیٹھ کے پیچھے رکھ چھوڑا تھا اور اپنے ایک ہاتھ کی ہتھیلی پر ٹیک لگائے ہوئے تھا، آپ نے فرمایا: \"کیا تم ان لوگوں کی طرح بیٹھتے ہو جن پر غضب نازل ہوا؟\"۔"],"14297":["bukhari",6272,"ہم سے محمد بن ابی غالب نے بیان کیا، کہا ہم کو ابراہیم بن المنذر حزامی نے خبر دی، کہا ہم سے محمد بن فلیح نے بیان کیا، ان سے ان کے باپ نے، ان سے نافع نے اور ان سے ابن عمر رضی اللہ عنہما نے بیان کیا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو صحن کعبہ میں دیکھا کہ آپ سرین پر بیٹھے ہوئے دونوں رانیں شکم مبارک سے ملائے ہوئے ہاتھوں سے پنڈلی پکڑے ہوئے بیٹھے تھے۔"],"14298":["bukhari",2654,"ہم سے مسدد نے بیان کیا، کہا ہم سے بشر بن مفضل نے بیان کیا، کہا ہم سے جریر نے بیان کیا ان سے عبدالرحمٰن بن ابی بکرہ نے اور ان سے ان کے باپ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ میں تم لوگوں کو سب سے بڑے گناہ نہ بتاؤں؟ تین بار آپ صلی اللہ علیہ وسلم نے اسی طرح فرمایا۔ صحابہ نے عرض کیا، ہاں یا رسول! آپ صلی اللہ علیہ وسلم نے فرمایا، اللہ کا کسی کو شریک ٹھہرانا، ماں باپ کی نافرمانی کرنا، آپ صلی اللہ علیہ وسلم اس وقت تک ٹیک لگائے ہوئے تھے لیکن اب آپ صلی اللہ علیہ وسلم سیدھے بیٹھ گئے اور فرمایا، ہاں اور جھوٹی گواہی بھی۔ انہوں نے بیان کیا کہ آپ صلی اللہ علیہ وسلم نے اس جملے کو اتنی مرتبہ دہرایا کہ ہم کہنے لگے کاش! آپ صلی اللہ علیہ وسلم خاموش ہو جاتے۔ اسماعیل بن ابراہیم نے بیان کیا، ان سے جریری نے بیان کیا، اور ان سے عبدالرحمٰن نے بیان کیا۔ 11- بَابُ شَهَادَةِ الأَعْمَى، وَأَمْرِهِ وَنِكَاحِهِ وَإِنْكَاحِهِ وَمُبَايَعَتِهِ وَقَبُولِهِ فِي التَّأْذِينِ وَغَيْرِهِ، وَمَا يُعْرَفُ بِالأَصْوَاتِ:"],"14299":["bukhari",6277,"ہم سے اسحاق بن شاہین واسطی نے بیان کیا، کہا ہم سے خالد نے بیان کیا (دوسری سند) امام بخاری رحمہ اللہ نے کہا اور مجھ سے عبداللہ بن محمد مسندی نے بیان کیا، ان سے عمرو بن عون نے بیان کیا، ان سے خالد (خالد بن عبداللہ طحان) نے بیان کیا، ان سے خالد (خالد حذاء) نے، ان سے ابوقلابہ نے بیان کیا، کہا کہ مجھے ابوالملیح عامر بن زید نے خبر دی، انہوں نے (ابوقلابہ) کو (خطاب کر کے) کہا کہ میں تمہارے والد زید کے ساتھ عبداللہ بن عمر رضی اللہ عنہما کی خدمت میں حاضر ہوا، انہوں نے ہم سے بیان کیا کہ نبی کریم صلی اللہ علیہ وسلم سے میرے روزے کا ذکر کیا گیا۔ نبی کریم صلی اللہ علیہ وسلم میرے یہاں تشریف لائے میں نے آپ کے لیے چمڑے کا ایک گدا، جس میں کھجور کی چھال بھری ہوئی تھی بچھا دیا۔ نبی کریم صلی اللہ علیہ وسلم زمین پر بیٹھے اور گدا میرے اور نبی کریم صلی اللہ علیہ وسلم کے درمیان ویسا ہی پڑا رہا۔ پھر نبی کریم صلی اللہ علیہ وسلم نے مجھ سے فرمایا کہ کیا تمہارے لیے ہر مہینے میں تین دن کے (روزے) کافی نہیں؟ میں نے عرض کیا: یا رسول اللہ! نبی کریم صلی اللہ علیہ وسلم نے فرمایا پھر پانچ دن رکھا کر۔ میں نے عرض کیا: یا رسول اللہ! فرمایا سات دن۔ میں نے عرض کیا: یا رسول اللہ! فرمایا نو دن۔ میں نے عرض کیا: یا رسول اللہ! فرمایا گیارہ دن۔ میں نے عرض کیا یا رسول اللہ! فرمایا داؤد علیہ السلام کے روزے سے زیادہ کوئی روزہ نہیں ہے۔ زندگی کے نصف ایام، ایک دن کا روزہ اور ایک دن بغیر روزہ کے رہنا۔"],"14300":["bukhari",6271,"ہم سے حسن بن عمر نے بیان کیا، کہا ہم سے معتمر بن سلیمان نے، کہا میں نے اپنے والد سے سنا، وہ ابومجلز (حق بن حمید) سے بیان کرتے تھے اور ان سے انس بن مالک رضی اللہ عنہ نے بیان کیا کہ جب رسول اللہ صلی اللہ علیہ وسلم نے زینب بنت جحش رضی اللہ عنہ سے نکاح کیا تو لوگوں کو (دعوت ولیمہ پر) بلایا۔ لوگوں نے کھانا کھایا پھر بیٹھ کر باتیں کرتے رہے بیان کیا کہ پھر نبی کریم صلی اللہ علیہ وسلم نے ایسا کیا گویا آپ اٹھنا چاہتے ہیں۔ لیکن لوگ (پھر بھی بیٹھے ہوئے تھے) پھر بھی کھڑے نہیں ہوئے۔ جب نبی کریم صلی اللہ علیہ وسلم نے یہ دیکھا تو آپ کھڑے ہو گئے جب نبی کریم صلی اللہ علیہ وسلم کھڑے ہوئے تو آپ کے ساتھ اور بھی بہت سے صحابہ کھڑے ہو گئے لیکن تین آدمی اب بھی باقی رہ گئے۔ اس کے بعد نبی کریم صلی اللہ علیہ وسلم اندر جانے کے لیے تشریف لائے لیکن وہ لوگ اب بھی بیٹھے ہوئے تھے۔ اس کے بعد وہ لوگ بھی چلے گئے۔ انس رضی اللہ عنہ نے بیان کیا کہ پھر میں آیا اور میں نے نبی کریم صلی اللہ علیہ وسلم کو اطلاع دی کہ وہ (تین آدمی) بھی جا چکے ہیں۔ نبی کریم صلی اللہ علیہ وسلم تشریف لائے اور اندر داخل ہو گئے۔ میں نے بھی اندر جانا چاہا لیکن نبی کریم صلی اللہ علیہ وسلم نے میرے اور اپنے درمیان پردہ ڈال لیا اور اللہ تعالیٰ نے یہ آیت نازل کی «يا أيها الذين آمنوا لا تدخلوا بيوت النبي إلا أن يؤذن لكم» اے ایمان والو! نبی کے گھر میں اس وقت تک داخل نہ ہو جب تک تمہیں اجازت نہ دی جائے۔ ارشاد ہوا «إن ذلكم كان عند الله عظيما» تک۔"],"14301":["abudawud",4868,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب کوئی شخص کوئی بات کرے، پھر ادھر ادھر مڑ مڑ کر دیکھے تو وہ امانت ہے (اسے افشاء نہیں کرنا چاہیئے)\"۔"],"14302":["bukhari",5376,"ہم سے علی بن عبداللہ مدینی نے بیان کیا، کہا ہم کو سفیان ثوری نے خبر دی، کہا کہ مجھے ولید بن کثیر نے خبر دی، انہوں نے وہب بن کیسان سے سنا، انہوں نے عمر بن ابی سلمہ رضی اللہ عنہ سے سنا، انہوں نے بیان کیا کہ میں بچہ تھا اور رسول اللہ صلی اللہ علیہ وسلم کی پرورش میں تھا اور (کھاتے وقت) میرا ہاتھ برتن میں چاروں طرف گھوما کرتا۔ اس لیے آپ صلی اللہ علیہ وسلم نے مجھ سے فرمایا کہ بیٹے! بسم اللہ پڑھ لیا کرو، داہنے ہاتھ سے کھایا کرو اور برتن میں وہاں سے کھایا کرو جو جگہ تجھ سے نزدیک ہو۔ چنانچہ اس کے بعد میں ہمیشہ اسی ہدایت کے مطابق کھاتا رہا۔"],"14303":["muslim",5272,"ابو معاویہ نے اعمش سے ، انھوں نے خیثمہ سے ، انھوں ن ابوحذیفہ سے ، انھوں نے سیدنا حذیفہ رضی اللہ تعالی عنہ سے روایت کی ، کہا : کہ جب ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ کھانا کھاتے تو اپنے ہاتھ نہ ڈالتے جب تک آپ صلی اللہ علیہ وسلم شروع نہ کرتے اور ہاتھ نہ ڈالتے ۔ ایک دفعہ ہم آپ صلی اللہ علیہ وسلم کے ساتھ کھانے پر موجود تھے اور ایک لڑکی دوڑتی ہوئی آئی جیسے کوئی اس کو ہانک رہا ہے اور اس نے اپنا ہاتھ کھانے میں ڈالنا چاہا تو آپ صلی اللہ علیہ وسلم نے اس کا ہاتھ پکڑ لیا ۔ پھر ایک دیہاتی دوڑتا ہوا آیا تو آپ صلی اللہ علیہ وسلم نے اس کا ہاتھ تھام لیا ۔ پھر فرمایا کہ شیطان اس کھانے پر قدرت پا لیتا ہے جس پر اللہ تعالی کا نام نہ لیا جائے اور وہ ایک لڑکی کو اس کھانے پر قدرت حاصل کرنے کو لایا تو میں نے اس کا ہاتھ پکڑ لیا ، پھر اس دیہاتی کو اسی غرض سے لایا تو میں نے اس کا بھی ہاتھ پکڑ لیا ، قسم اس کی جس کے ہاتھ میں میری جان ہے!اس ( شیطان ) کا ہاتھ اس لڑکی کے ہاتھ کے ساتھ میرے ہاتھ میں ہے ۔"],"14304":["muslim",5275,"ابو عاصم نے ابن جریج سے روایت کی ، کہا : مجھے ابو زبیر نے سیدنا جابر بن عبداللہ رضی اللہ تعالی عنہ سے خبر دی ، انھوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا : \" کہ جب آدمی اپنے گھر میں جاتا ہے ، اور گھر میں داخل ہوتے وقت اور کھانا کھاتے وقت اللہ جل جلالہ کا نام لیتا ہے ، تو شیطان ( اپنے رفیقوں اور تابعداروں سے ) کہتا ہے کہ نہ تمہارے یہاں رہنے کا ٹھکانہ ہے ، نہ کھانا ہے اور جب گھر میں داخل ہوتے وقت اللہ تعالی کا نام نہیں لیتا تو شیطان کہتا ہے کہ تمہیں رہنے کا ٹھکانہ تو مل گیا اور جب کھاتے وقت بھی اللہ تعالی کا نام نہیں لیتا تو شیطان کہتا ہے کہ تمہارے رہنے کا ٹھکانہ بھی ہوا اور کھانا بھی ملا ۔"],"14306":["muslim",5278,"سفیان نے زہری سے ، انھوں نے ابو بکر بن عبیداللہ بن عبداللہ بن عمر سے ، انھوں نے اپنے دادا سیدنا ابن عمر رضی اللہ تعالی عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب تم میں سے کوئی شخص کھاناکھائے تو اپنے دائیں ہاتھ سے کھائے اور جب تم میں سے کوئی شخص پیےتواپنے دائیں ہاتھ سے پیے کیونکہ شیطان بائیں ہاتھ سے کھاتاہے اور بائیں ہاتھ سے پیتا ہے ۔"],"14308":["ibnmajah",3266,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تم میں ہر شخص کو چاہیئے کہ وہ دائیں ہاتھ سے کھائے، دائیں ہاتھ سے پیئے، دائیں ہاتھ سے لے، دائیں ہاتھ سے دے، اس لیے کہ شیطان بائیں ہاتھ سے کھاتا ہے، بائیں ہاتھ سے پیتا ہے، بائیں ہاتھ سے دیتا ہے اور بائیں ہاتھ سے لیتا ہے\"۔"],"14309":["muslim",5277,"سیدنا جابر رضی اللہ تعالی عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" بائیں ہاتھ سے نہ کھاؤ کیونکہ شیطان بائیں ہاتھ سے کھاتاہے ۔"],"14310":["muslim",5278,"سفیان نے زہری سے ، انھوں نے ابو بکر بن عبیداللہ بن عبداللہ بن عمر سے ، انھوں نے اپنے دادا سیدنا ابن عمر رضی اللہ تعالی عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب تم میں سے کوئی شخص کھاناکھائے تو اپنے دائیں ہاتھ سے کھائے اور جب تم میں سے کوئی شخص پیےتواپنے دائیں ہاتھ سے پیے کیونکہ شیطان بائیں ہاتھ سے کھاتاہے اور بائیں ہاتھ سے پیتا ہے ۔"],"14311":["malik",5,"ابوہریرہ رضی اللہ تعالی عنہ روایت ہے کہ فرمایا رسول اللہ صلی اللہ علیہ وسلم نے جس شخص نے پا لی ایک رکعت نماز صبح کی آفتاب نکلنے سے پہلے تو پا چکا وہ صبح کو اور جس شخص نے پا لی ایک رکعت نماز عصر کی آفتاب ڈوبنے سے پہلے تو پا چکا وہ نماز عصر کو ۔"],"14313":["bukhari",5377,"مجھ سے عبدالعزیز بن عبداللہ اویسی نے بیان کیا، انہوں نے کہا کہ مجھ سے محمد بن جعفر نے بیان کیا، ان سے محمد بن عمرو بن حلحلہ دیلی نے بیان کیا، ان سے وہب بن کیسان ابونعیم نے بیان کیا، ان سے عمر بن ابی سلمہ رضی اللہ عنہ نے، وہ نبی کریم صلی اللہ علیہ وسلم کی زوجہ مطہرہ ام سلمہ رضی اللہ عنہا کے (ابوسلمہ سے) بیٹے ہیں۔ بیان کیا کہ ایک دن میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ کھانا کھایا اور برتن کے چاروں طرف سے کھانے لگا تو نبی کریم صلی اللہ علیہ وسلم نے مجھ سے فرمایا کہ اپنے نزدیک سے کھا۔"],"14314":["abudawud",3772,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی کھانا کھائے تو پلیٹ کے اوپری حصے سے نہ کھائے بلکہ اس کے نچلے حصہ سے کھائے اس لیے کہ برکت اس کے اوپر والے حصہ میں نازل ہوتی ہے\"۔"],"14318":["malik",51,"ابان بن عثمان سے روایت ہے کہ عثمان بن عفان نے روٹی اور گوشت کھا کر کلی کی اور ہاتھ دھو کر منہ پونچھا پھر نماز پڑھی اور وضو نہ کیا ۔ امام مالک کو پہنچا سیدنا علی اور عبداللہ بن عباس سے کہ وہ دونوں وضو نہ کرتے تھے اس کھانے سے جو آگ سے پکا ہو ۔"],"14319":["shamail",135,"’’سیدنا ابوجحیفہ رضی اللہ عنہ سے مروی ہے وہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میں تو ٹیک لگا کر کھانا نہیں کھاتا۔‘‘"],"14321":["muslim",5346,"حفص بن غیاث نے مصعب بن سلیم سے روایت کی ، کہا : ہمیں سیدنا انس بن ما لک رضی اللہ تعالی عنہ نے حدیث بیان کی ، کہا : میں نے دیکھا کہ رسول اللہ صلی اللہ علیہ وسلم دونوں گھٹنے کھڑےکر کے تھوڑے سے زمین پر لگ کر بیٹھے تھے ۔ کھجوریں کھا رہے تھے ۔"],"14322":["muslim",5346,"حفص بن غیاث نے مصعب بن سلیم سے روایت کی ، کہا : ہمیں سیدنا انس بن ما لک رضی اللہ تعالی عنہ نے حدیث بیان کی ، کہا : میں نے دیکھا کہ رسول اللہ صلی اللہ علیہ وسلم دونوں گھٹنے کھڑےکر کے تھوڑے سے زمین پر لگ کر بیٹھے تھے ۔ کھجوریں کھا رہے تھے ۔"],"14323":["bukhari",5399,"مجھ سے عثمان بن ابی شیبہ نے بیان کیا، کہا ہم کو جریر نے خبر دی، انہیں منصور نے، انہیں علی ابن الاقمر نے اور ان سے ابوجحیفہ رضی اللہ عنہ نے بیان کیا کہ میں نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر تھا۔ آپ صلی اللہ علیہ وسلم نے ایک صحابی سے جو آپ کے پاس موجود تھے فرمایا کہ میں ٹیک لگا کر نہیں کھاتا۔"],"14324":["abudawud",3770,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کبھی ٹیک لگا کر کھاتے ہوئے نہیں دیکھے گئے، اور نہ ہی آپ کے پیچھے دو آدمیوں کو چلتے دیکھا گیا (بلکہ آپ صلی اللہ علیہ وسلم بیچ میں یا سب سے پیچھے چلا کرتے تھے) ۔"],"14325":["abudawud",3773,"عبداللہ بن بسر رضی اللہ عنہ کا بیان ہے کہ نبی اکرم صلی اللہ علیہ وسلم کا ایک لگن جسے غراء کہا جاتا تھا، اور جسے چار آدمی اٹھاتے تھے، جب اشراق کا وقت ہوا اور لوگوں نے اشراق کی نماز پڑھ لی تو وہ لگن لایا گیا، مطلب یہ ہے اس میں ثریدبھرا ہوا تھا تو سب اس کے اردگرد اکٹھا ہو گئے، جب لوگوں کی تعداد بڑھ گئی تو رسول اللہ صلی اللہ علیہ وسلم گھٹنے ٹیک کر بیٹھ گئےایک اعرابی کہنے لگا: بھلا یہ بیٹھنے کا کون سا طریقہ ہے؟ تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی نے مجھے نیک (متواضع) بندہ بنایا ہے، مجھے جبار و سرکش نہیں بنایا ہے\" پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس کے کناروں سے کھاؤ اور اوپر کا حصہ چھوڑ دو کیونکہ اس میں برکت دی جاتی ہے\"۔"],"14326":["muslim",5313,"سفیان بن عینیہ نے ابو زبیر سے ، انھوں نے سیدنا جابر رضی اللہ تعالی عنہ سے روایت کی کہ نبی کریم صلی اللہ علیہ وسلم نے انگلیاں اور پیالہ چاٹنے کا حکم دیا اور فرمایا : \" تم نہیں جانتے اس کے کس حصے میں برکت ہے ۔"],"14327":["muslim",5319,"بہز نے کہا : ہمیں حماد بن سلمہ نے حدیث بیان کی ، کہا : ہمیں ثابت نے سیدنا انس رضی اللہ تعالی عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم جس وقت کھانا کھاتے تو ( آخر میں ) اپنی تین انگلیوں کو چاٹتے اور کہا : آپ نے فرمایا : \" جب تم میں سے کسی کا لقمہ گر جائے تو وہ اس سے ناپسندیدہ چیز کو دور کرلے اور کھالے اور اس کو شیطان کے لئے نہ چھوڑے ۔ \" اورآپ نے ہمیں پیالہ صاف کرنے کا حکم دیا اور فرمایا : \" تم نہیں جانتے کہ تمھارے کھانے کے کس حصے میں برکت ہے ۔"],"14328":["bukhari",5456,"ہم سے علی بن عبداللہ نے بیان کیا، انہوں نے کہا ہم سے سفیان نے بیان کیا، ان سے عمرو بن دینار نے، ان سے عطاء نے اور ان سے ابن عباس رضی اللہ عنہما نے بیان کیا کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ جب کوئی شخص کھانا کھائے تو ہاتھ چاٹنے یا کسی کو چٹانے سے پہلے ہاتھ نہ پونچھے۔"],"14329":["muslim",5313,"سفیان بن عینیہ نے ابو زبیر سے ، انھوں نے سیدنا جابر رضی اللہ تعالی عنہ سے روایت کی کہ نبی کریم صلی اللہ علیہ وسلم نے انگلیاں اور پیالہ چاٹنے کا حکم دیا اور فرمایا : \" تم نہیں جانتے اس کے کس حصے میں برکت ہے ۔"],"14330":["muslim",5320,"سیدنا ابو ہریرہ رضی اللہ تعالی عنہ نے نبی کریم صلی اللہ علیہ وسلم سے ر وایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" جب تم میں سے کوئی شخص کھاناکھائے تو اپنی انگلیوں کو چاٹ لے ، کیونکہ وہ نہیں جانتا کہ ان میں سے کس میں برکت ہے ۔"],"14331":["muslim",5309,"ابو بکر بن ابی شیبہ ، زہیر بن حرب اور محمد بن حاتم نے کہا : ہمیں ابن مہدی نے سفیان سے حدیث بیان کی ، انھوں نے سعد بن ابراہیم سے ، انھوں نے سیدنا کعب بن مالک رضی اللہ تعالی عنہ کے بیٹے سے اور انھوں نے اپنے والد سے روایت کی ، کہا : میں نے د یکھا کہ نبی کریم صلی اللہ علیہ وسلم کھانے کے بعد اپنی تین انگلیاں چاٹ رہ تھے ۔ ابن حاتم نے تین کا ذکر نہیں کیا ، اور ابن ابی شیبہ کی روایت میں ( ابن کعب بن مالک کے بجائے ) عبدالرحمان بن کعب سے روایت ہے ، انھوں نے اپنے والد سے روایت کی ، کے الفاظ ہیں ۔"],"14332":["bukhari",5456,"ہم سے علی بن عبداللہ نے بیان کیا، انہوں نے کہا ہم سے سفیان نے بیان کیا، ان سے عمرو بن دینار نے، ان سے عطاء نے اور ان سے ابن عباس رضی اللہ عنہما نے بیان کیا کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ جب کوئی شخص کھانا کھائے تو ہاتھ چاٹنے یا کسی کو چٹانے سے پہلے ہاتھ نہ پونچھے۔"],"14333":["bukhari",5457,"ہم سے ابراہیم بن المنذر نے بیان کیا، کہا کہ مجھ سے محمد بن فلیح نے بیان کیا، کہا کہ مجھ سے میرے والد نے، ان سے سعید بن الحارث نے اور ان سے جابر بن عبداللہ رضی اللہ عنہما نے کہ سعید بن الحارث نے جابر رضی اللہ عنہ سے ایسی چیز کے (کھانے کے بعد) جو آگ پر رکھی ہو وضو کے متعلق پوچھا (کہ کیا ایسی چیز کھانے سے وضو ٹوٹ جاتا ہے؟) تو انہوں نے کہا کہ نہیں۔ نبی کریم صلی اللہ علیہ وسلم کے زمانہ میں ہمیں اس طرح کا کھانا (جو پکا ہوا ہوتا) بہت کم میسر آتا تھا اور اگر میسر آ بھی جاتا تھا تو سوا ہماری ہتھیلیوں بازوؤں اور پاؤں کے کوئی رومال نہیں ہوتا تھا (اور ہم انہیں سے اپنے ہاتھ صاف کر کے) نماز پڑھ لیتے تھے اور وضو۔"],"14334":["muslim",5313,"سفیان بن عینیہ نے ابو زبیر سے ، انھوں نے سیدنا جابر رضی اللہ تعالی عنہ سے روایت کی کہ نبی کریم صلی اللہ علیہ وسلم نے انگلیاں اور پیالہ چاٹنے کا حکم دیا اور فرمایا : \" تم نہیں جانتے اس کے کس حصے میں برکت ہے ۔"],"14336":["abudawud",3852,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص سو جائے اور اس کے ہاتھ میں گندگی اور چکنائی ہو اور وہ اسے نہ دھوئے پھر اس کو کوئی نقصان پہنچے تو وہ اپنے آپ ہی کو ملامت کرے\"۔"],"14338":["bukhari",5409,"ہم سے محمد بن کثیر نے بیان کیا، کہا ہم کو سفیان نے خبر دی، انہیں اعمش نے، انہیں ابوحازم نے اور ان سے ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ نبی کریم صلی اللہ علیہ وسلم نے کبھی کسی کھانے میں کوئی عیب نہیں نکالا۔ اگر پسند ہوا تو کھا لیا اور اگر ناپسند ہوا تو چھوڑ دیا۔"],"14339":["malik",20,"عبداللہ بن عباس کہتے تھے کہ دلوک الشمس جب ہوتا ہے کہ سایہ پلٹے پچھم سے پورب کو اور غسق اللیل رات کا گزرنا اور اندھیر اس کا ۔"],"14340":["muslim",5383,"اسحاق بن ابراہیم اور یحیی بن حبیب نے روح بن عبادہ سے حدیث بیان کی ، کہا : ہمیں ابن جریج نےبتایا ، کہا : مجھے ابو زبیر نے خبر دی کہ انھوں نے سیدنا جابر بن عبداللہ رضی اللہ تعالی عنہ سے سنا ، وہ کہہ رہے تھے : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا کہ آپ فرمارہے تھے : \"\" ایک آدمی کا کھانا دو کےلیے کافی ہوجاتا ہے ۔ اور دو کا کھانا چار کے لئے کافی ہوجاتا ہے ۔ اور چار کا کھانا آٹھ کے لئے کافی ہوجاتا ہے ۔ \"\" اور اسحاق کی روایت میں ہے : ( سیدنا جابر رضی اللہ تعالی عنہ نے کہا : ) رسول اللہ صلی اللہ علیہ وسلم نےفرمایا : \"\" میں نے سنا \"\" کے الفاظ ذکر نہیں کیے ۔"],"14341":["malik",9,"عبداللہ بن رافع جو آنحضرت صلی اللہ علیہ وسلم کی بی بی ام سلمہ کے مولی ہیں انہوں نے پوچھا ابوہریرہ رضی اللہ تعالی عنہ نماز کا وقت، کہا ابوہریرہ نے میں بتاؤں تجھ کو نماز پڑھ ظہر کی جب سایہ تیرا تیرے برابر ہو جائے اور عصر کی جب سایہ تیرا تجھ سے دوگنا ہو اور مغرب کی جب آفتاب ڈوب جائے اور عشاء کی تہائی رات کی اور صبح کی اندھیرے منہ ۔"],"14342":["bukhari",5397,"ہم سے سلیمان بن حرب نے بیان کیا، انہوں نے کہا ہم سے شعبہ نے بیان کیا، ان سے عدی بن ثابت نے بیان کیا، ان سے ابوحازم نے بیان کیا اور ان سے ابوہریرہ رضی اللہ عنہ نے کہ ایک صاحب بہت زیادہ کھانا کھایا کرتے تھے، پھر وہ اسلام لائے تو کم کھانے لگے۔ اس کا ذکر رسول اللہ صلی اللہ علیہ وسلم سے کیا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا کہ مومن ایک آنت میں کھاتا ہے اور کافر ساتوں آنتوں میں کھاتا ہے۔"],"14343":["malik",10,"انس بن مالک کہتے ہیں کہ ہم نماز عصر کی پڑھتے تھے ساتھ رسول اللہ صلی اللہ علیہ وسلم کے مدینہ میں پھر ہم میں سے کوئی جاتا بنی عمرو بن عوف کے محلہ میں تو پاتا ان کو عصر کی نماز میں۔"],"14344":["bukhari",5393,"ہم سے محمد بن بشار نے بیان کیا، ہم سے سے عبدالصمد بن عبدالوارث نے بیان کیا، کہا ہم سے شعبہ بن حجاج نے بیان کیا، ان سے واقد بن محمد نے، ان سے نافع نے بیان کیا کہ ابن عمر رضی اللہ عنہما اس وقت تک کھانا نہیں کھاتے تھے، جب تک ان کے ساتھ کھانے کے لیے کوئی مسکین نہ لایا جاتا۔ ایک مرتبہ میں ان کے ساتھ کھانے کے لیے ایک شخص کو لایا کہ اس نے بہت زیادہ کھانا کھایا۔ بعد میں ابن عمر رضی اللہ عنہما نے کہا کہ آئندہ اس شخص کو میرے ساتھ کھانے کے لیے نہ لانا۔ میں نے نبی کریم صلی اللہ علیہ وسلم سے سنا ہے کہ مومن ایک آنت میں کھاتا اور کافر دو آنتیں بھر لیتا ہے۔"],"14345":["bukhari",5395,"ہم سے علی بن عبداللہ نے بیان کیا، انہوں نے کہا ہم سے سفیان بن عیینہ نے بیان کیا، ان سے عمرو بن دینار نے کہ ابونہیک بڑے کھانے والے تھے۔ ان سے عبداللہ بن عمر رضی اللہ عنہما نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے کہ کافر ساتوں آنتوں میں کھاتا ہے۔ ابونہیک نے اس پر عرض کیا کہ میں اللہ اور اس کے رسول پر ایمان رکھتا ہوں۔"],"14346":["muslim",5390,"عبد الرحمٰن نے سفیان سے ، انھوں نے ابو زبیر سے انھوں نے سیدنا جا بر اور ابن عمر رضی اللہ تعالی عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرما یا : \" مومن ایک آنت سے کھا تا ہے جبکہ کافر سات آنتوں میں کھا تا ہے ۔"],"14347":["muslim",5392,"سیدنا ابو موسی رضی اللہ تعالی عنہ نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرما یا : \" مومن ایک آنت میں کھا تا ہے جبکہ کا فر سات آنتوں میں کھا تا ہے ۔"],"14350":["malik",19,"روایت ہے نافع سے کہ عبداللہ بن عمر کہتے تھے دلوک الشمس سے آفتاب کا ڈھلنا مراد ہے ۔"],"14351":["bukhari",5382,"ہم سے موسیٰ بن اسماعیل نے بیان کیا، کہا ہم سے معتمر بن سلیمان نے بیان کیا، ان سے ان کے والد نے بیان کیا، انہوں نے کہا کہ ابوعثمان نہدی نے بھی بیان کیا اور ان سے عبدالرحمٰن بن ابی بکر رضی اللہ عنہما نے بیان کیا کہ ہم ایک سو تیس آدمی نبی کریم صلی اللہ علیہ وسلم کے ساتھ تھے۔ نبی کریم صلی اللہ علیہ وسلم نے دریافت فرمایا کہ تم میں سے کسی کے پاس کھانا ہے۔ ایک صاحب نے اپنے پاس سے ایک صاع کے قریب آٹا نکالا، اسے گوندھ لیا گیا، پھر ایک مشرک لمبا تڑنگا اپنی بکریاں ہانکتا ہوا ادھر آ گیا۔ نبی کریم صلی اللہ علیہ وسلم نے اس سے دریافت فرمایا کہ یہ بیچنے کی ہیں یا عطیہ ہیں یا نبی کریم صلی اللہ علیہ وسلم نے (عطیہ کے بجائے) ہبہ فرمایا۔ اس شخص نے کہا کہ نہیں بلکہ بیچنے کی ہیں۔ چنانچہ نبی کریم صلی اللہ علیہ وسلم نے اس سے ایک بکری خریدی پھر ذبح کی گئی اور آپ نے اس کی کلیجی بھونے جانے کا حکم دیا اور قسم اللہ کی ایک سو تیس لوگوں کی جماعت میں کوئی شخص ایسا نہیں رہا جسے نبی کریم صلی اللہ علیہ وسلم نے اس بکری کی کلیجی کا ایک ایک ٹکڑا کاٹ کر نہ دیا ہو مگر وہ موجود تھا تو اسے وہیں دے دیا اور اگر وہ موجود نہیں تھا تو اس کا حصہ محفوظ رکھا، پھر اس بکری کے گوشت کو پکا کر دو بڑے کونڈوں میں رکھا اور ہم سب نے ان میں سے پیٹ بھر کر کھایا پھر بھی دونوں کونڈوں میں کھانا بچ گیا تو میں نے اسے اونٹ پر لاد لیا۔ عبدالرحمٰن راوی نے ایسا ہی کوئی کلمہ کہا۔"],"14352":["bukhari",5383,"ہم سے مسلم بن ابراہیم قصاب نے بیان کیا، کہا ہم سے وہیب بن خالد نے بیان کیا، کہا ہم سے منصور بن عبدالرحمٰن نے بیان کیا، ان سے ان کی والدہ (صفیہ بن شبیہ) نے اور ان سے عائشہ رضی اللہ عنہا نے کہ نبی کریم صلی اللہ علیہ وسلم کی وفات ہوئی، ان دنوں ہم پانی اور کھجور سے سیر ہو جانے لگے تھے۔"],"14353":["muslim",5328,"خلف بن خلیفہ نے یزید بن کیسان سے ، انھوں نے ابوحازم سے ، انھوں نے سیدنا ابوہریرہ رضی اللہ تعالی عنہ سے روایت کی ، کہا : کہ رسول اللہ صلی اللہ علیہ وسلم ایک دفعہ رات یا دن کو باہر نکلے اور آپ صلی اللہ علیہ وسلم نے سیدنا ابوبکر اور عمر رضی اللہ عنہما کو دیکھا تو پوچھا کہ تمہیں اس وقت کون سی چیز گھر سے نکال لائی ہے؟ انہوں نے کہا کہ یا رسول اللہ! بھوک کے مارے ۔ آپ صلی اللہ علیہ وسلم نے فرمایا کہ قسم اس کی جس کے ہاتھ میں میری جان ہے ، میں بھی اسی وجہ سے نکلا ہوں ، چلو ۔ پھر وہ آپ صلی اللہ علیہ وسلم کے ساتھ چلے ، آپ صلی اللہ علیہ وسلم ایک انصاری کے دروازے پر آئے ، وہ اپنے گھر میں نہیں تھا ۔ اس کی عورت نے آپ صلی اللہ علیہ وسلم کو دیکھا تو اس نے خوش آمدید کہا ۔ آپ صلی اللہ علیہ وسلم نے فرمایا کہ فلاں شخص ( اس کے خاوند کے متعلق فرمایا ) کہاں گیا ہے؟ وہ بولی کہ ہمارے لئے میٹھا پانی لینے گیا ہے ( اس حدیث سے معلوم ہوا کہ عذر سے اجنبی عورت سے بات کرنا اور اس کو جواب دینا درست ہے ، اسی طرح عورت اس مرد کو گھر بلا سکتی ہے جس کے آنے سے خاوند راضی ہو ) اتنے میں وہ انصاری مرد آ گیا تو اس نے رسول اللہ صلی اللہ علیہ وسلم اور آپ صلی اللہ علیہ وسلم کے دونوں ساتھیوں کو دیکھا تو کہا کہ اللہ تعالی کا شکر ہے کہ آج کے دن کسی کے پاس ایسے مہمان نہیں ہیں جیسے میرے پاس ہیں ۔ پھر گیا اور کھجور کا ایک خوشہ لے کر آیا جس میں گدر ، سوکھی اور تازہ کھجوریں تھیں اور کہنے لگا کہ اس میں سے کھائیے پھر اس نے چھری لی تو آپ صلی اللہ علیہ وسلم نے فرمایا کہ دودھ والی بکری مت کاٹنا ۔ اس نے ایک بکری کاٹی اور سب نے اس کا گوشت کھایا اور کھجور بھی کھائی اور پانی پیا ۔ جب کھانے پینے سے سیر ہوئے تو رسول اللہ صلی اللہ علیہ وسلم نے سیدنا ابوبکر اور عمر رضی اللہ عنہما سے فرمایا کہ قسم اس کی جس کے ہاتھ میں میری جان ہے ، قیامت کے دن تم سے اس نعمت کے بارے میں سوال ہو گا کہ تم اپنے گھروں سے بھوک کے مارے نکلے اور نہیں لوٹے یہاں تک کہ تمہیں یہ نعمت ملی ۔ ( اس فضل پر سوال ضرور ہوگا)"],"14354":["bukhari",673,"ہم سے عبید بن اسماعیل نے بیان کیا ابواسامہ حماد بن اسامہ سے، انہوں نے عبیداللہ سے، انہوں نے نافع سے، انہوں نے عبداللہ بن عمر رضی اللہ عنہما سے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ جب تم میں سے کسی کا شام کا کھانا تیار ہو چکا ہو اور تکبیر بھی کہی جا چکی ہو تو پہلے کھانا کھا لو اور نماز کے لیے جلدی نہ کرو، کھانے سے فراغت کر لو۔ اور عبداللہ بن عمر رضی اللہ عنہما کے لیے کھانا رکھ دیا جاتا، ادھر اقامت بھی ہو جاتی لیکن آپ کھانے سے فارغ ہونے تک نماز میں شریک نہیں ہوتے تھے۔ آپ امام کی قرآت برابر سنتے رہتے تھے۔"],"14355":["bukhari",672,"ہم سے یحیی بن بکیر نے بیان کیا، انہوں نے کہا کہ ہم سے لیث بن سعد نے بیان کیا، انہوں نے عقیل سے، انہوں نے ابن شہاب سے بیان کیا، انہوں نے انس بن مالک رضی اللہ عنہ سے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ جب شام کا کھانا حاضر کیا جائے تو مغرب کی نماز سے پہلے کھانا کھا لو اور کھانے میں بے مزہ بھی نہ ہونا چاہئے اور اپنا کھانا چھوڑ کر نماز میں جلدی مت کرو۔"],"14356":["bukhari",671,"تو انہوں نے فرمایا کہ میں نے عبداللہ بن عباس رضی اللہ عنہما سے سنا تھا کہ نبی کریم صلی اللہ علیہ وسلم نے ایک رات عشاء کی نماز میں دیر کی جس کے نتیجہ میں لوگ (مسجد ہی میں) سو گئے۔ پھر بیدار ہوئے پھر سو گئے ، پھر بیدار ہوئے۔ آخر میں عمر بن خطاب رضی اللہ عنہ اٹھے اور پکارا نماز عطاء نے کہا کہ ابن عباس رضی اللہ عنہما نے بتلایا کہ اس کے بعد نبی کریم صلی اللہ علیہ وسلم گھر سے تشریف لائے۔ وہ منظر میری نگاہوں کے سامنے ہے جب کہ آپ صلی اللہ علیہ وسلم کے سر مبارک سے پانی کے قطرے ٹپک رہے تھے اور آپ ہاتھ سر پر رکھے ہوئے تھے۔ آپ نے فرمایا کہ اگر میری امت کے لیے مشکل نہ ہو جاتی، تو میں انہیں حکم دیتا کہ عشاء کی نماز کو اسی وقت پڑھیں۔ میں نے عطاء سے مزید تحقیق چاہی کہ نبی کریم صلی اللہ علیہ وسلم کے ہاتھ سر پر رکھنے کی کیفیت کیا تھی؟ ابن عباس رضی اللہ عنہما نے انہیں اس سلسلے میں کس طرح خبر دی تھی۔ اس پر عطاء نے اپنے ہاتھ کی انگلیاں تھوڑی سی کھول دیں اور انہیں سر کے ایک کنارے پر رکھا پھر انہیں ملا کر یوں سر پر پھیرنے لگے کہ ان کا انگوٹھا کان کے اس کنارے سے جو چہرے سے قریب ہے اور داڑھی سے جا لگا۔ نہ سستی کی اور نہ جلدی، بلکہ اس طرح کیا اور کہا کہ پھر نبی کریم صلی اللہ علیہ وسلم نے فرمایا کہ اگر میری امت پر مشکل نہ گزرتی تو میں حکم دیتا کہ اس نماز کو اسی وقت پڑھا کریں۔ 25- بَابُ وَقْتِ الْعِشَاءِ إِلَى نِصْفِ اللَّيْلِ: ہم سے مسدد بن مسرہد نے بیان کیا، کہا کہ ہم سے یحیی بن سعید قطان نے ہشام بن عروہ سے بیان کیا، کہا کہ مجھ سے میرے باپ نے بیان کیا، انہوں نے عائشہ رضی اللہ عنہا سے سنا، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے کہ آپ صلی اللہ علیہ وسلم نے فرمایا کہ اگر شام کا کھانا سامنے رکھا جائے اور ادھر نماز کے لیے تکبیر بھی ہونے لگے تو پہلے کھانا کھا لو۔"],"14357":["abudawud",3762,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ایک پہاڑ کی گھاٹی سے قضائے حاجت سے فارغ ہو کر آئے اس وقت ہمارے سامنے ڈھال پر کچھ کھجوریں رکھیں تھیں، ہم نے آپ صلی اللہ علیہ وسلم کو بلایا تو آپ نے ہمارے ساتھ کھایا اور پانی کو ہاتھ نہیں لگایا۔"],"14358":["bukhari",5400,"ہم سے علی بن عبداللہ نے بیان کیا، کہا ہم سے ہشام بن یوسف نے بیان کیا، کہا ہم کو معمر نے خبر دی، انہیں زہری نے، انہیں ابوامامہ بن سہل نے اور انہیں ابن عباس رضی اللہ عنہما نے کہ خالد بن ولید رضی اللہ عنہ نے بیان کیا کہ نبی کریم صلی اللہ علیہ وسلم کے لیے بھنا ہوا ساہنہ پیش کیا گیا تو آپ اسے کھانے کے لیے متوجہ ہوئے۔ اسی وقت آپ کو بتایا گیا کہ یہ ساہنہ ہے تو آپ صلی اللہ علیہ وسلم نے اپنا ہاتھ روک لیا۔ خالد رضی اللہ عنہ نے پوچھا کیا یہ حرام ہے؟ فرمایا کہ نہیں لیکن چونکہ یہ میرے ملک میں نہیں ہوتا اس لیے طبیعت اسے گوارا نہیں کرتی۔ پھر خالد رضی اللہ عنہ نے اسے کھایا اور نبی کریم صلی اللہ علیہ وسلم دیکھ رہے تھے۔ امام مالک نے ابن شہاب سے «ضب محنوذ.» (یعنی بھنا ہوا ساہنہ «ضب مشوی» کی جگہ «محنوذ.» نقل کیا، دونوں لفظوں کا ایک معنی ہے)۔"],"14359":["bukhari",5407,"اور مجھ سے عبدالعزیز بن عبداللہ اویسی نے بیان کیا، کہا ہم سے محمد بن جعفر نے بیان کیا، ان سے ابوحازم نے بیان کیا، ان سے عبداللہ بن ابی قتادہ اسلمی نے، ان سے ان کے والد نے بیان کیا کہ میں ایک دن نبی کریم صلی اللہ علیہ وسلم کے چند صحابہ کے ساتھ مکہ کے راستہ میں ایک منزل پر بیٹھا ہوا تھا۔ نبی کریم صلی اللہ علیہ وسلم نے ہمارے آگے پڑاؤ کیا تھا۔ صحابہ کرام رضی اللہ عنہم احرام کی حالت میں تھے لیکن میں احرام میں نہیں تھا۔ لوگوں نے ایک گورخر کو دیکھا۔ میں اس وقت اپنا جوتا ٹانکنے میں مصروف تھا۔ ان لوگوں نے مجھے اس گورخر کے متعلق بتایا کچھ نہیں لیکن چاہتے تھے کہ میں کسی طرح دیکھ لوں۔ چنانچہ میں متوجہ ہوا اور میں نے اسے دیکھ لیا، پھر میں گھوڑے کے پاس گیا اور اسے زین پہنا کر اس پر سوار ہو گیا لیکن کوڑا اور نیزہ بھول گیا تھا۔ میں نے ان لوگوں سے کہا کہ کوڑا اور نیزہ مجھے دے دو۔ انہوں نے کہا کہ نہیں اللہ کی قسم! ہم تمہاری شکار کے معاملہ میں کوئی مدد نہیں کریں گے۔ (کیونکہ ہم محرم ہیں)میں غصہ ہو گیا اور میں نے اتر کر خود یہ دونوں چیزیں اٹھائیں پھر سوار ہو کر اس پر حملہ کیا اور ذبح کر لیا۔ جب وہ ٹھنڈا ہو گیا تو میں اسے ساتھ لایا پھر پکا کر میں نے اور سب نے کھایا لیکن بعد میں انہیں شبہ ہوا کہ احرام کی حالت میں اس (شکار کا گوشت) کھانا کیسا ہے؟ پھر ہم روانہ ہوئے اور میں نے اس کا گوشت چھپا کر رکھا۔ جب نبی کریم صلی اللہ علیہ وسلم کے پاس آئے تو ہم نے آپ سے اس کے متعلق پوچھا۔ آپ صلی اللہ علیہ وسلم نے دریافت فرمایا، تمہارے پاس کچھ بچا ہوا بھی ہے؟ میں نے وہی دست پیش کیا اور آپ صلی اللہ علیہ وسلم نے بھی اسے کھایا۔ یہاں تک کہ اس کا گوشت آپ نے اپنے دانتوں سے کھینچ کھینچ کر کھایا اور آپ احرام میں تھے۔ محمد بن جعفر نے بیان کیا کہ مجھ سے زید بن اسلم نے یہ واقعہ بیان کیا، ان سے عطاء بن یسار نے اور ان سے ابوقتادہ رضی اللہ عنہ نے اسی طرح سارا واقعہ بیان کیا۔"],"14360":["bukhari",5404,"ہم سے عبداللہ بن عبدالوہاب نے بیان کیا، کہا ہم سے حماد بن زید نے بیان کیا، کہا ہم سے ایوب سختیانی نے بیان کیا، ان سے محمد بن سیرین نے اور ان سے ابن عباس رضی اللہ عنہما نے کہ نبی کریم صلی اللہ علیہ وسلم نے شانے کی ہڈی کا گوشت کھایا، پھر کھڑے ہوئے اور نماز پڑھی۔ آپ صلی اللہ علیہ وسلم نے (نماز کے لیے نیا) وضو نہیں کیا اور (اسی سند سے)۔"],"14361":["bukhari",5408,"ہم سے ابوالیمان نے بیان کیا، کہا ہم کو شعیب نے خبر دی، ان سے زہری نے بیان کیا، انہیں جعفر بن عمرو بن امیہ ضمری نے خبر دی، انہیں ان کے والد عمرو بن امیہ رضی اللہ عنہ نے خبر دی کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کو دیکھا آپ اپنے ہاتھ سے بکری کے شانے کا گوشت کاٹ کر کھا رہے تھے، پھر آپ صلی اللہ علیہ وسلم کو نماز کے لیے بلایا گیا تو آپ نے گوشت اور وہ چھری جس سے گوشت کی بوٹی کاٹ رہے تھے، ڈال دی اور نماز کے لیے کھڑے ہو گئے، پھر آپ صلی اللہ علیہ وسلم نے نماز پڑھی اور آپ نے نیا وضو نہیں کیا (کیونکہ آپ پہلے ہی وضو کئے ہوئے تھے)۔"],"14362":["abudawud",188,"مغیرہ بن شعبہ رضی اللہ عنہ کہتے ہیں کہ میں ایک رات نبی اکرم صلی اللہ علیہ وسلم کا مہمان ہوا تو آپ نے بکری کی ران بھوننے کا حکم دیا، وہ بھونی گئی، آپ صلی اللہ علیہ وسلم نے چھری لی، اور میرے لیے اس میں سے گوشت کاٹنے لگے، اتنے میں بلال رضی اللہ عنہ آئے، اور آپ صلی اللہ علیہ وسلم کو نماز کی خبر دی، تو آپ نے چھری رکھ دی، اور فرمایا: \"اسے کیا ہو گیا؟ اس کے دونوں ہاتھ خاک آلود ہوں؟\"، اور اٹھ کر نماز پڑھنے کھڑے ہوئے۔ انباری کی روایت میں اتنا اضافہ ہے: \"میری موچھیں بڑھ گئی تھیں، تو آپ صلی اللہ علیہ وسلم نے مونچھوں کے تلے ایک مسواک رکھ کر ان کو کتر دیا\"، یا فرمایا: \"میں ایک مسواک رکھ کر تمہارے یہ بال کتر دوں گا\"۔"],"14363":["shamail",160,"’’سیدنا عبداللہ بن حارث رضی اللہ عنہ سے مروی وہ فرماتے ہیں کہ ہم نے مسجد میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ بھنا ہوا گوشت کھایا۔‘‘"],"14364":["muslim",285,"ابو اشہب نے حسن ( بصری ) سے حدیث بیان کی ، انہوں نے کہا : عبید اللہ بن زیاد نےسیدنا معقل بن یسار مزنی رضی اللہ عنہ کے مرض ا لموت میں ان کی عیادت کی تو معقل رضی اللہ عنہ نے اس سے کہا : میں تمہیں ایک حدیث سنانے لگا ہوں جو میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنی ۔ اگر میں جانتا کہ میں ا بھی اور زندہ رہوں گا تو تمہیں یہ حدیث نہ سناتا ۔ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا : ’’ کوئی ایسا بندہ جسے اللہ کسی رعایا کا نگران بناتا ہے اور مرنے کے دن وہ اس حالت میں مرتا ہے کہ اپنی رعیت سے دھوکا کرنے والا ہے تو اللہ اس پر جنت حرام کر دیتا ہے ۔ ‘‘"],"14365":["ibnmajah",3362,"ابوذر رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب تم سالن پکاؤ تو اس میں شوربا بڑھا لو، اور اس میں سے ایک ایک چمچہ پڑوسیوں کو بھجوا دو\"۔"],"14368":["bukhari",3340,"مجھ سے اسحاق بن نصر نے بیان کیا، ہم سے محمد بن عبید نے بیان کیا، ہم سے ابوحیان یحیی بن سعید نے بیان کیا، ان سے ابوزرعہ نے اور ان سے ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ ہم نبی کریم صلی اللہ علیہ وسلم کے ساتھ ایک دعوت میں شریک تھے۔ آپ صلی اللہ علیہ وسلم کی خدمت میں دستی کا گوشت پیش کیا گیا جو آپ صلی اللہ علیہ وسلم کو بہت مرغوب تھا۔ آپ صلی اللہ علیہ وسلم نے اس دستی کی ہڈی کا گوشت دانتوں سے نکال کر کھایا۔ پھر فرمایا کہ میں قیامت کے دن لوگوں کا سردار ہوں گا۔ تمہیں معلوم ہے کہ کس طرح اللہ تعالیٰ (قیامت کے دن) تمام مخلوق کو ایک چٹیل میدان میں جمع کرے گا؟ اس طرح کہ دیکھنے والا سب کو ایک ساتھ دیکھ سکے گا۔ آواز دینے والے کی آواز ہر جگہ سنی جا سکے گی اور سورج بالکل قریب ہو جائے گا۔ ایک شخص اپنے قریب کے دوسرے شخص سے کہے گا، دیکھتے نہیں کہ سب لوگ کیسی پریشانی میں مبتلا ہیں؟ اور مصیبت کس حد تک پہنچ چکی ہے؟ کیوں نہ کسی ایسے شخص کی تلاش کی جائے جو اللہ پاک کی بارگاہ میں ہم سب کی شفاعت کے لیے جائے۔ کچھ لوگوں کا مشورہ ہو گا کہ دادا آدم علیہ السلام اس کے لیے مناسب ہیں۔ چنانچہ لوگ ان کی خدمت میں حاضر ہوں گے اور عرض کریں گے، اے باوا آدم! آپ انسانوں کے دادا ہیں۔ اللہ پاک نے آپ کو اپنے ہاتھ سے پیدا کیا تھا، اپنی روح آپ کے اندر پھونکی تھی، ملائکہ کو حکم دیا تھا اور انہوں نے آپ کو سجدہ کیا تھا اور جنت میں آپ کو (پیدا کرنے کے بعد) ٹھہرایا تھا۔ آپ اپنے رب کے حضور میں ہماری شفاعت کر دیں۔ آپ خود ملاحظہ فرما سکتے ہیں کہ ہم کس درجہ الجھن اور پریشانی میں مبتلا ہیں۔ وہ فرمائیں گے کہ (گناہ گاروں پر) اللہ تعالیٰ آج اس درجہ غضبناک ہے کہ کبھی اتنا غضبناک نہیں ہوا تھا اور نہ آئندہ کبھی ہو گا اور مجھے پہلے ہی درخت (جنت) کے کھانے سے منع کر چکا تھا لیکن میں اس فرمان کو بجا لانے میں کوتاہی کر گیا۔ آج تو مجھے اپنی ہی پڑی ہے (نفسی نفسی) تم لوگ کسی اور کے پاس جاؤ۔ ہاں، نوح علیہ السلام کے پاس جاؤ۔ چنانچہ سب لوگ نوح علیہ السلام کی خدمت میں حاضر ہوں گے اور عرض کریں گے، اے نوح علیہ السلام! آپ (آدم علیہ السلام کے بعد) روئے زمین پر سب سے پہلے نبی ہیں اور اللہ تعالیٰ نے آپ کو عبدشکور کہہ کر پکارا ہے۔ آپ ملاحظہ فرما سکتے ہیں کہ آج ہم کیسی مصیبت و پریشانی میں مبتلا ہیں؟ آپ اپنے رب کے حضور میں ہماری شفاعت کر دیجئیے۔ وہ بھی یہی جواب دیں گے کہ میرا رب آج اس درجہ غضبناک ہے کہ اس سے پہلے کبھی ایسا غضبناک نہیں ہوا تھا اور نہ کبھی اس کے بعد اتنا غضبناک ہو گا۔ آج تو مجھے خود اپنی ہی فکر ہے۔ (نفسی نفسی) تم نبی کریم صلی اللہ علیہ وسلم کی خدمت میں جاؤ چنانچہ وہ لوگ میرے پاس آئیں گے۔ میں (ان کی شفاعت کے لیے) عرش کے نیچے سجدے میں گر پڑوں گا۔ پھر آواز آئے گی، اے محمد! سر اٹھاؤ اور شفاعت کرو، تمہاری شفاعت قبول کی جائے گی۔ مانگو تمہیں دیا جائے گا۔ محمد بن عبیداللہ نے بیان کیا کہ ساری حدیث میں یاد نہ رکھ سکا۔"],"14369":["tirmidhi",1835,"عبداللہ بن حارث کہتے ہیں کہ میرے باپ نے میری شادی کی اور لوگوں کو مدعو کیا، ان میں صفوان بن امیہ رضی اللہ عنہ بھی تھے، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"گوشت کو دانت سے نوچ کر کھاؤ اس لیے کہ وہ زیادہ جلد ہضم ہوتا ہے، اور لذیذ ہوتا ہے\"۔"],"14370":["bukhari",5408,"ہم سے ابوالیمان نے بیان کیا، کہا ہم کو شعیب نے خبر دی، ان سے زہری نے بیان کیا، انہیں جعفر بن عمرو بن امیہ ضمری نے خبر دی، انہیں ان کے والد عمرو بن امیہ رضی اللہ عنہ نے خبر دی کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کو دیکھا آپ اپنے ہاتھ سے بکری کے شانے کا گوشت کاٹ کر کھا رہے تھے، پھر آپ صلی اللہ علیہ وسلم کو نماز کے لیے بلایا گیا تو آپ نے گوشت اور وہ چھری جس سے گوشت کی بوٹی کاٹ رہے تھے، ڈال دی اور نماز کے لیے کھڑے ہو گئے، پھر آپ صلی اللہ علیہ وسلم نے نماز پڑھی اور آپ نے نیا وضو نہیں کیا (کیونکہ آپ پہلے ہی وضو کئے ہوئے تھے)۔"],"14371":["bukhari",5446,"ہم سے آدم نے بیان کیا، کہا ہم سے شعبہ نے بیان کیا، کہا ہم سے جبلہ بن سحیم نے بیان کیا، کہا کہ ہمیں عبداللہ بن زبیر رضی اللہ عنہما کے ساتھ (جب وہ حجاز کے خلیفہ تھے) ایک سال قحط کا سامنا کرنا پڑا تو انہوں نے راشن میں ہمیں کھانے کے لیے کھجوریں دیں۔ عبداللہ بن عمر رضی اللہ عنہما ہمارے پاس سے گزرتے اور ہم کھجور کھاتے ہوتے تو وہ فرماتے کہ دو کھجوروں کو ایک ساتھ ملا کر نہ کھاؤ کیونکہ نبی کریم صلی اللہ علیہ وسلم نے دو کھجوروں کو ایک ساتھ ملا کر کھانے سے منع کیا ہے۔ پھر فرمایا سوا اس صورت کے جب اس کو کھانے والا شخص اپنے ساتھی سے (جو کھانے میں شریک ہے) اس کی اجازت لے لے۔ شعبہ نے بیان کیا کہ اجازت والا ٹکڑا ابن عمر رضی اللہ عنہما کا قول ہے۔"],"14372":["muslim",5343,"محمد بن جعفر نے کہا : ہمیں شعبہ نے یزید بن خمیر سے ، انھوں نے سیدنا عبد اللہ بن بسر رضی اللہ تعالی عنہ سے روایت کی کہا : رسول اللہ صلی اللہ علیہ وسلم میرے والد کے ہاں مہمان ہو ئے ہم نے رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں کھجور پنیر اور گھی سے تیار کیا ہوا حلوہ پیش کیا ، آپ نے اس میں سے تناول فرما یا ، پھر آپ کے سامنے کھجور یں پیش کی گئیں تو آپ کھجوریں کھا رہے تھے ۔ اور گٹھلیاں اپنی دو انگلیوں کے درمیان ڈالتے جا رہے تھے ۔ ( کھا نے کے لیے ) آپ صلی اللہ علیہ وسلم نے شہادت کی اور درمیانی انگلی اکٹھی کی ہوئی تھیں ۔ شعبہ نے کہا : میر اگمان ( غالب ) ہے اور ان شاء اللہ یہ بات یعنی گٹھلیوں کو دو انگلیوں کے درمیان ڈالنا اس ( حدیث ) میں ہے ۔ پھر ( آپ کےسامنے ) مشروب لا یا گیا ۔ آپ نے اسے پیا ، پھر اپنی دائیں جا نب والے کو دے دیا ۔ ( عبد اللہ بن بسر رضی اللہ تعالی عنہ نے ) کہا : تو میرے والد نے جب انھوں نے آپ صلی اللہ علیہ وسلم کی سواری کی لگا م پکڑی ہو ئی تھی عرض کی : ہمارے لیے اللہ سے دعا فرما ئیے ۔ تو رسول اللہ صلی اللہ علیہ وسلم نے ( دعا کرتے ہو ئے ) فرما یا \" اے اللہ !تونے انھیں جو رزق دیا ہے اس میں ان کے لیے برکت ڈال دے اور ان کے گناہ بخش دے اور ان پر رحم فرما ۔"],"14373":["bukhari",5386,"ہم سے علی بن عبداللہ مدینی نے بیان کیا، کہا ہم سے معاذ بن ہشام نے بیان کیا، کہا کہ مجھ سے میرے والد نے بیان کیا، ان سے یونس نے، علی بن عبداللہ المدینی نے کہا کہ یہ یونس اسکاف ہیں (نہ کہ یونس بن عبید بصریٰ) ان سے قتادہ نے اور ان سے انس رضی اللہ عنہ نے بیان کیا کہ میں نہیں جانتا کہ نبی کریم صلی اللہ علیہ وسلم نے کبھی تشتری رکھ کر (ایک وقت مختلف قسم کا) کھانا کھایا ہو اور نہ کبھی آپ نے پتلی روٹیاں (چپاتیاں) کھائیں اور نہ کبھی آپ صلی اللہ علیہ وسلم نے میز پر کھایا۔ قتادہ سے پوچھا گیا کہ پھر کس چیز پر آپ کھاتے تھے؟ کہا کہ آپ سفرہ (عام دستر خوان) پر کھانا کھایا کرتے تھے۔"],"14374":["bukhari",5387,"ہم سے سعید بن مریم نے بیان کیا، کہا ہم کو محمد بن جعفر نے خبر دی، کہا مجھ کو حمید نے خبر دی اور انہوں نے انس رضی اللہ عنہ سے سنا، انہوں نے بیان کیا کہ نبی کریم صلی اللہ علیہ وسلم نے صفیہ رضی اللہ عنہا سے نکاح کے بعد ان کے ساتھ راستے میں قیام کیا اور میں نے مسلمانوں کو آپ کے ولیمہ کی دعوت میں بلایا۔ نبی کریم صلی اللہ علیہ وسلم نے دستر خوان بچھانے کا حکم دیا اور وہ بچھایا گیا، پھر آپ نے اس پر کھجور، پنیر اور گھی ڈال دیا اور عمرو بن ابی عمرو نے کہا، ان سے انس رضی اللہ عنہ نے کہ نبی کریم صلی اللہ علیہ وسلم نے صفیہ رضی اللہ عنہا کے ساتھ صحبت کی، پھر ایک چمڑے کے دستر خوان پر (کھجور، گھی، پنیر ملا کر بنا ہوا) حلوہ رکھا۔"],"14375":["bukhari",5389,"ہم سے ابونعمان نے بیان کیا، انہوں نے کہا ہم سے ابوعوانہ نے بیان کیا، ان سے ابوبشر نے، ان سے سعید بن جبیر نے اور ان سے ابن عباس رضی اللہ عنہما نے بیان کیا کہ ابن عباس رضی اللہ عنہما کی خالہ ام حفید بنت حارث بن حزن رضی اللہ عنہا نے نبی کریم صلی اللہ علیہ وسلم کو گھی، پنیر اور ساہنہ ہدیہ کے طور پر بھیجی۔ نبی کریم صلی اللہ علیہ وسلم نے عورتوں کو بلایا اور انہوں نے آپ کے دستر خوان پر ساہنہ کو کھایا لیکن آپ صلی اللہ علیہ وسلم نے اسے ہاتھ بھی نہیں لگایا جیسے آپ صلی اللہ علیہ وسلم اسے ناپسند کرتے ہیں۔ لیکن اگر ساہنہ حرام ہوتا تو آپ کے دستر خوان پر کھایا نہ جاتا اور نہ آپ انہیں کھانے کے لیے فرماتے۔"],"14376":["muslim",5287,"ہمام نے کہا : ہمیں قتادہ نے حدیث بیان کی ، انھوں نے سیدنا انس رضی اللہ تعالی عنہ سے روایت کی کہ نبی کریم صلی اللہ علیہ وسلم نے کھڑے ہوکرپانی پینے سے ڈانٹ کر منع فرمایا ۔"],"14377":["muslim",5290,"ہمام نے کہا : قتادہ نے ہمیں ابو عیسی اُسواری سے حدیث بیان کی ، انھوں نے سیدنا ابوسعید خدری رضی اللہ تعالی عنہ سے روایت کی کہ نبی کریم صلی اللہ علیہ وسلم نے کھڑے ہوکر پانی پینے سے ڈانٹ کرروکا ۔"],"14378":["muslim",5292,"ابوغطفان مری سے روایت ہے کہ انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالی عنہ سے سنا ، کہہ رہے تھے ، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم میں سے کوئی شخص کھڑے ہوکر ہر گز نہ پیے اور جس نے بھول کرکھڑے ہوکر پی لیا ، وہ قے کردے ۔"],"14381":["tirmidhi",1881,"جارود بن معلی رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے کھڑے ہو کر پینے سے منع فرمایا۔"],"14382":["bukhari",5617,"ہم سے ابونعیم نے بیان کیا، کہا ہم سے سفیان نے بیان کیا، ان سے عاصم احول نے، ان سے شعبی نے اور ان سے عبداللہ بن عباس رضی اللہ عنہما نے بیان کیا کہ نبی کریم صلی اللہ علیہ وسلم نے زمزم کا پانی کھڑے ہو کر پیا۔"],"14383":["bukhari",5616,"ہم سے آدم نے بیان کیا، کہا ہم سے شعبہ نے بیان کیا، کہا ہم سے عبدالملک بن میسرہ نے بیان کیا، انہوں نے نزال بن سبرہ سے سنا، وہ علی رضی اللہ عنہ سے بیان کرتے تھے کہ انہوں نے ظہر کی نماز پڑھی پھر مسجد کوفہ کے صحن میں لوگوں کی ضرورتوں کے لیے بیٹھ گئے۔ اس عرصہ میں عصر کی نماز کا وقت آ گیا پھر ان کے پاس پانی لایا گیا۔ انہوں نے پانی پیا اور اپنا چہرہ اور ہاتھ دھوئے، ان کے سر اور پاؤں (کے دھونے کا بھی) ذکر کیا۔ پھر انہوں نے کھڑے ہو کر وضو کا بچا ہوا پانی پیا، اس کے بعد کہا کہ کچھ لوگ کھڑے ہو کر پانی پینے کو برا سمجھتے ہیں حالانکہ نبی کریم صلی اللہ علیہ وسلم نے یونہی کیا تھا جس طرح میں نے کیا، وضو کا پانی کھڑے ہو کر پیا۔"],"14384":["bukhari",5615,"ہم سے ابونعیم نے بیان کیا، کہا ہم سے مسعر نے بیان کیا، ان سے عبدالملک بن میسرہ نے، ان سے نزال نے بیان کیا کہ وہ علی رضی اللہ عنہ کی خدمت میں مسجد کوفہ کے صحن میں حاضر ہوئے پھر علی رضی اللہ عنہ نے کھڑے ہو کر پیا اور کہا کہ کچھ لوگ کھڑے ہو کر پانی پینے کو مکروہ سمجھتے ہیں حالانکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو اس طرح کرتے دیکھا ہے جس طرح تم نے مجھے اس وقت کھڑے ہو کر پانی پیتے دیکھا ہے۔"],"14386":["bukhari",5618,"ہم سے مالک بن اسماعیل نے بیان کیا، کہا ہم سے عبدالعزیز بن ابی سلمہ نے بیان کیا، کہا ہم کو ابوالنضر نے خبر دی، انہیں ابن عباس رضی اللہ عنہما کے غلام عمیر نے اور انہیں ام فضل بنت حارث نے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کے لیے دودھ کا ایک پیالہ بھیجا میدان عرفات میں۔ وہ عرفہ کے دن کی شام کا وقت تھا اور نبی کریم صلی اللہ علیہ وسلم (اپنی سواری پر) سوار تھے، آپ نے اپنے ہاتھ میں وہ پیالہ لیا اور اسے پی لیا۔ مالک نے ابوالنضر سے اپنے اونٹ پر کے الفاظ زیادہ کئے۔"],"14387":["tirmidhi",1892,"کبشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم میرے گھر تشریف لائے، آپ نے ایک لٹکی ہوئی مشکیزہ کے منہ سے کھڑے ہو کر پانی پیا، پھر میں مشکیزہ کے منہ کے پاس گئی اور اس کو کاٹ لیا۔"],"14388":["tirmidhi",1880,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے زمانہ میں چلتے ہوئے کھاتے تھے اور کھڑے ہو کر پیتے تھے۔"],"14389":["abudawud",653,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا ہے کہ آپ ننگے پاؤں نماز پڑھتے اور جوتے پہن کر بھی۔"],"14391":["muslim",5298,"ثمامہ بن عبداللہ بن انس نے سیدنا انس رضی اللہ تعالی عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم برتن میں ( سے پانی پیتے ہوئے اس سے منہ ہٹا کر ) تین مرتبہ سانس لیتے تھے ۔"],"14392":["bukhari",5631,"ہم سے ابوعاصم اور ابونعیم نے بیان کیا، انہوں نے کہا کہ ہم سے عروہ بن ثابت نے بیان کیا، انہوں نے کہا کہ مجھے شمامہ بن عبداللہ نے خبر دی، بیان کیا کہ انس رضی اللہ عنہ دو یا تین سانسوں میں پانی پیتے تھے۔"],"14394":["tirmidhi",1887,"عبداللہ بن مغفل رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کنگھی کرنے سے منع فرمایا، سوائے اس کے کہ ناغہ کر کے کی جائے۔ حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، عَنْ هِشَامٍ، عَنْ الْحَسَنِ، بِهَذَا الْإِسْنَادِ نَحْوَهُ، قَالَ أَبُو عِيسَى: هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ، قَالَ: وَفِي الْبَاب، عَنْ أَنَسٍ. اس سند سے بھی عبداللہ بن مغفل رضی اللہ عنہ سے اسی جیسی روایت ہے۔ ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے پینے کی چیز میں پھونکنے سے منع فرمایا، ایک آدمی نے عرض کیا: برتن میں کوئی ناپسندیدہ چیز دیکھوں تو کیا کروں؟ آپ نے فرمایا: \"اسے بہا دو، اس نے عرض کیا: میں ایک سانس میں سیراب نہیں ہو پاتا ہوں، آپ نے فرمایا: \"تب (سانس لیتے وقت) پیالہ اپنے منہ سے ہٹا لو\"۔"],"14395":["bukhari",5630,"ہم سے ابونعیم نے بیان کیا، کہا ہم سے شیبان نے بیان کیا، ان سے یحیی بن ابی کثیر نے، ان سے عبداللہ بن ابی قتادہ نے، ان سے ان کے والد نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ جب تم میں سے کوئی شخص پانی پئے تو (پینے کے) برتن میں (پانی پیتے ہوئے) سانس نہ لے اور جب تم میں سے کوئی شخص پیشاب کرے تو داہنے ہاتھ کو ذکر پر نہ پھیرے اور جب استنجاء کرے تو داہنے ہاتھ سے نہ کرے۔"],"14396":["ibnmajah",3427,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی کچھ پئے تو برتن میں سانس نہ لے، اور اگر سانس لینا چاہے تو برتن کو منہ سے علیحدہ کر لے، پھر اگر چاہے تو دوبارہ پئے\"۔"],"14397":["tirmidhi",1887,"عبداللہ بن مغفل رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کنگھی کرنے سے منع فرمایا، سوائے اس کے کہ ناغہ کر کے کی جائے۔ حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، عَنْ هِشَامٍ، عَنْ الْحَسَنِ، بِهَذَا الْإِسْنَادِ نَحْوَهُ، قَالَ أَبُو عِيسَى: هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ، قَالَ: وَفِي الْبَاب، عَنْ أَنَسٍ. اس سند سے بھی عبداللہ بن مغفل رضی اللہ عنہ سے اسی جیسی روایت ہے۔ ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے پینے کی چیز میں پھونکنے سے منع فرمایا، ایک آدمی نے عرض کیا: برتن میں کوئی ناپسندیدہ چیز دیکھوں تو کیا کروں؟ آپ نے فرمایا: \"اسے بہا دو، اس نے عرض کیا: میں ایک سانس میں سیراب نہیں ہو پاتا ہوں، آپ نے فرمایا: \"تب (سانس لیتے وقت) پیالہ اپنے منہ سے ہٹا لو\"۔"],"14398":["abudawud",3728,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے برتن میں سانس لینے یا پھونک مارنے سے منع فرمایا ہے۔"]});